INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('01cdef7e-6816-5523-82a8-370271114ee3', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 7, 7, 'What happens to the mean kinetic energy of the molecules of a pure substance while it is melting at constant temperature?', NULL, 1, 'multiple_choice'::answer_type, 'It stays the same', NULL, false, NULL, false, NULL, 'Temperature measures the mean kinetic energy of the molecules. While melting the temperature is constant, so the mean Ek is constant; the energy supplied increases the potential energy (breaking bonds). Mark scheme (1 mark). B1: C (It stays the same).', 1, NULL, NULL),
('b9ac0f89-46fc-5d60-97ce-23c406c52734', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 8, 8, 'Energy is supplied to boiling water but its temperature stays at 100 °C. Where does the energy go?', NULL, 1, 'multiple_choice'::answer_type, 'Into increasing the potential energy of the molecules as they separate', NULL, false, NULL, false, NULL, 'During a change of state the energy breaks intermolecular bonds, increasing molecular potential energy, not kinetic energy. Mark scheme (1 mark). B1: A (Into increasing the potential energy of the molecules as they separate).', 1, NULL, NULL),
('7b9e89fa-f991-5392-a6a9-3e539d9e8327', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 9, 9, 'Which describes evaporation?', NULL, 1, 'multiple_choice'::answer_type, 'The escape of the most energetic molecules from the surface of a liquid at any temperature', NULL, false, NULL, false, NULL, 'Evaporation happens only at the surface and at any temperature; boiling happens throughout at one temperature. Mark scheme (1 mark). B1: D (The escape of the most energetic molecules from the surface of a liquid at any temperature).', 1, NULL, NULL),
('673cef50-0d2a-5a29-bc09-322f6e5cb5d8', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 10, 10, 'Why does evaporation cool the liquid left behind?', NULL, 1, 'multiple_choice'::answer_type, 'The fastest molecules leave, so the mean kinetic energy of those left decreases', NULL, false, NULL, false, NULL, 'Losing the highest-energy molecules lowers the average kinetic energy of the remaining ones, so the temperature falls. Mark scheme (1 mark). B1: B (The fastest molecules leave, so the mean kinetic energy of those left decreases).', 1, NULL, NULL),
('4e01f556-e603-5c05-a61f-74071f8d624f', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 11, 11, 'A 2.5 kg block of ice taken from a cold store at its melting point is left to turn completely into water at 0 °C. How much energy does it absorb from the room? Take the specific latent heat of fusion of ice as 3.34 × 10⁵ J kg⁻¹.', NULL, 1, 'numeric'::answer_type, '8.35e5', 'J', false, NULL, false, NULL, 'E = mL_f = 2.5 × 3.34 × 10⁵ = 8.35 × 10⁵ J. Mark scheme (2 marks). C1: E = mL. A1: E = 8.35 × 10⁵ J.', 2, NULL, NULL),
('ce322f48-9970-5187-ab36-4ba047aa4f24', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 12, 12, 'How much energy must a kettle supply to turn 0.40 kg of boiling water at 100 °C completely into steam? Take the specific latent heat of vaporisation of water as 2.26 × 10⁶ J kg⁻¹.', NULL, 1, 'numeric'::answer_type, '9.04e5', 'J', false, NULL, false, NULL, 'E = mL_v = 0.40 × 2.26 × 10⁶ = 9.04 × 10⁵ J. Mark scheme (2 marks). C1: E = mL. A1: E = 9.04 × 10⁵ J.', 2, NULL, NULL),
('a7ccbe91-a13d-5e0c-be63-079a9c3e007d', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 13, 13, 'A freezer removes 6.68 × 10⁴ J from water at 0 °C, freezing it completely. What mass of ice is formed? Take the specific latent heat of fusion of ice as 3.34 × 10⁵ J kg⁻¹.', NULL, 1, 'numeric'::answer_type, '0.2', 'kg', false, NULL, false, NULL, 'm = E/L_f = 6.68 × 10⁴ ÷ 3.34 × 10⁵ = 0.200 kg. Mark scheme (2 marks). C1: m = E/L. A1: m = 0.200 kg.', 2, NULL, NULL),
('d09f7798-fec8-530b-a003-8acd13392f8f', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 14, 14, 'What is the specific latent heat of vaporisation of a substance?', NULL, 1, 'multiple_choice'::answer_type, 'The energy needed to change 1 kg of liquid into vapour at constant temperature', NULL, false, NULL, false, NULL, 'L_v = E/m for the liquid → gas change at its boiling point, without a temperature change. Mark scheme (1 mark). B1: C (The energy needed to change 1 kg of liquid into vapour at constant temperature).', 1, NULL, NULL),
('9229a0f8-7e5f-5523-ab37-c32946185ff2', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 15, 15, 'A hot sauna stone is splashed with water and steam forms. Which process releases energy?', NULL, 1, 'multiple_choice'::answer_type, 'Steam condensing on a person''s skin', NULL, false, NULL, false, NULL, 'Condensation releases the latent heat of vaporisation, which is why steam scalds more than water at 100 °C. Mark scheme (1 mark). B1: A (Steam condensing on a person''s skin).', 1, NULL, NULL),
('567a3b3d-9d5e-5979-9a51-b9e5fd620de1', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 16, 16, 'A 1.2 kW heater melts a block of wax at its melting point in 150 s. How much energy is supplied?', NULL, 1, 'numeric'::answer_type, '1.8e5', 'J', false, NULL, false, NULL, 'E = Pt = 1200 × 150 = 1.8 × 10⁵ J. Mark scheme (1 mark). A1: E = 1.8 × 10⁵ J.', 1, NULL, NULL),
('d5fa82c6-015e-5c0d-9527-cb890918ee08', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 17, 17, 'On a temperature–time graph for a substance heated at a steady rate, what does a horizontal section show?', NULL, 1, 'multiple_choice'::answer_type, 'A change of state', NULL, false, NULL, false, NULL, 'Energy is still being supplied, but it goes into changing the state, so the temperature stays constant. Mark scheme (1 mark). B1: D (A change of state).', 1, NULL, NULL),
('18a2d0dc-77e3-53eb-919e-61e148878b08', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 18, 18, 'Why is more energy needed to boil 1 kg of water than to melt 1 kg of ice?', NULL, 1, 'multiple_choice'::answer_type, 'Boiling separates the molecules completely and pushes back the atmosphere; melting only loosens the bonds', NULL, false, NULL, false, NULL, 'In vaporisation all bonds are broken and work is done against the atmosphere, so L_v ≫ L_f. Mark scheme (1 mark). B1: B (Boiling separates the molecules completely and pushes back the atmosphere; melting only loosens the bonds).', 1, NULL, NULL),
('bf9ac101-d638-5d2a-a8ab-9203cbe5f8b7', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 19, 19, 'A blacksmith quenches hot iron, and 0.15 kg of water at 100 °C boils away. How much energy did the water absorb in boiling? Take the specific latent heat of vaporisation of water as 2.26 × 10⁶ J kg⁻¹.', NULL, 1, 'numeric'::answer_type, '3.39e5', 'J', false, NULL, false, NULL, 'E = mL_v = 0.15 × 2.26 × 10⁶ = 3.39 × 10⁵ J. Mark scheme (2 marks). C1: E = mL_v. A1: E = 3.39 × 10⁵ J.', 2, NULL, NULL),
('f83699d7-78d7-5880-8312-47b9531e26cf', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 20, 20, 'Solid lead at its melting point needs 4.6 × 10³ J to melt 0.20 kg. Calculate the specific latent heat of fusion of lead.', NULL, 1, 'numeric'::answer_type, '23000', 'J kg⁻¹', false, NULL, false, NULL, 'L = E/m = 4.6 × 10³ ÷ 0.20 = 2.3 × 10⁴ J kg⁻¹. Mark scheme (2 marks). C1: L = E/m. A1: L = 2.3 × 10⁴ J kg⁻¹.', 2, NULL, NULL),
('5dc8a7af-93cb-5677-ad4d-fc881705ed2f', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 21, 21, 'Which change of state releases energy to the surroundings?', NULL, 1, 'multiple_choice'::answer_type, 'Freezing', NULL, false, NULL, false, NULL, 'Freezing releases the latent heat of fusion as bonds form. Mark scheme (1 mark). B1: C (Freezing).', 1, NULL, NULL),
('0fd24186-501c-5491-9fec-22677832b459', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 22, 22, 'An ice cube of mass 25 g at 0 °C melts in a drink. How much energy does it absorb in melting? Take the specific latent heat of fusion of ice as 3.34 × 10⁵ J kg⁻¹.', NULL, 1, 'numeric'::answer_type, '8350', 'J', false, NULL, false, NULL, 'E = mL = 0.025 × 3.34 × 10⁵ = 8350 J. Mark scheme (2 marks). C1: mass in kg. A1: E = 8350 J.', 2, NULL, NULL),
('b36f4a87-c729-5f16-a2ac-ccdd55b4084e', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 23, 23, 'Calculate the total energy needed to turn 0.50 kg of ice at −10 °C into water at 0 °C. The specific heat capacity of ice is 2100 J kg⁻¹ K⁻¹. Take the specific latent heat of fusion of ice as 3.34 × 10⁵ J kg⁻¹.', NULL, 2, 'numeric'::answer_type, '1.775e5', 'J', false, NULL, false, NULL, 'Warm the ice: 0.50 × 2100 × 10 = 1.05 × 10⁴ J. Melt it: 0.50 × 3.34 × 10⁵ = 1.67 × 10⁵ J. Total = 1.050 × 10⁴ + 1.670 × 10⁵ = 1.78 × 10⁵ J. Mark scheme (3 marks). C1: mcΔθ for ice. C1: mL_f. C1: total.', 3, NULL, NULL),
('ac6f4ea4-c63b-591a-84c1-0953828f1719', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 24, 24, 'A 2.0 kW kettle contains 0.80 kg of water at 100 °C. The kettle fails to switch off. Calculate how long it takes to boil away half the water, assuming all the energy goes to the water. Take the specific latent heat of vaporisation of water as 2.26 × 10⁶ J kg⁻¹.', NULL, 2, 'numeric'::answer_type, '452', 's', false, NULL, false, NULL, 'Mass boiled = 0.40 kg. E = mL_v = 0.40 × 2.26 × 10⁶ = 9.04 × 10⁵ J. t = E/P = 9.04 × 10⁵ ÷ 2000 = 452 s. Mark scheme (4 marks). C1: half the mass. C1: E = mL_v. C1: t = E/P. A1: t = 452 s.', 4, NULL, NULL),
('74ea98d5-062e-56e9-9706-75bed86782c2', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 25, 25, 'Steam at 100 °C condenses on a cold window and the water formed cools to 20 °C. Calculate the energy released per kilogram of steam. Take the specific latent heat of vaporisation of water as 2.26 × 10⁶ J kg⁻¹. Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.', NULL, 2, 'numeric'::answer_type, '2.596e6', 'J', false, NULL, false, NULL, 'Condensing: 2.26 × 10⁶ J. Cooling 1 kg of water by 80 K: 4200 × 80 = 3.36 × 10⁵ J. Total = 2.26 × 10⁶ + 3.360 × 10⁵ = 2.60 × 10⁶ J. Mark scheme (3 marks). C1: latent heat released. C1: mcΔθ for cooling. C1: total.', 3, NULL, NULL),
('ee06c64f-43b1-5664-a1dd-73e7f228d195', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 26, 26, 'Why does a scald from steam at 100 °C do much more damage than one from water at 100 °C?', NULL, 2, 'multiple_choice'::answer_type, 'Condensing steam releases its large latent heat to the skin before cooling', NULL, false, NULL, false, NULL, 'Each kg of steam gives out 2.26 MJ as it condenses, in addition to the energy released as the water cools. Mark scheme (3 marks). C1: latent heat released on condensing. C1: large compared with cooling. A1: A (Condensing steam releases its large latent heat to the skin before cooling).', 3, NULL, NULL),
('8d34ef7d-87a4-51d0-a3f8-7c4768a57376', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 27, 27, 'A student melts ice with a 60 W immersion heater. In 5.0 minutes, 0.052 kg of ice melts (allow for the ice melting due to the room by subtracting nothing). Calculate the specific latent heat of fusion found by the student.', NULL, 2, 'numeric'::answer_type, '3.462e5', 'J kg⁻¹', false, NULL, false, NULL, 'E = Pt = 60 × 300 = 18000 J. L = E/m = 18000 ÷ 0.052 = 3.46 × 10⁵ J kg⁻¹. Mark scheme (3 marks). C1: E = Pt. C1: t in s. C1: L = E/m.', 3, NULL, NULL),
('a5f5e11e-ec2c-5fa2-a935-857481edd7b7', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 28, 28, 'In an experiment to measure L_f, a control funnel with no heater collects 8 g of melted ice in the same time as the heated funnel collects 52 g. Why is the control used?', NULL, 2, 'multiple_choice'::answer_type, 'To subtract the ice melted by energy from the room, so only the heater''s energy is counted', NULL, false, NULL, false, NULL, 'The heater melted 52 − 8 = 44 g; using 52 g would give too small a value of L_f. Mark scheme (4 marks). C1: room melts some ice. C1: subtract control mass. C1: gives heater-only melting. A1: D (To subtract the ice melted by energy from the room, so only the heater''s energy is counted).', 4, NULL, NULL),
('3bba68dc-afd3-50ae-8064-64f9cf3ecdfa', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 29, 29, 'In the experiment above, the heater supplied 15 000 J. The heated funnel collected 52 g and the control collected 8 g. Calculate L_f.', NULL, 2, 'numeric'::answer_type, '3.409e5', 'J kg⁻¹', false, NULL, false, NULL, 'm = 0.052 − 0.008 = 0.044 kg. L = E/m = 15000 ÷ 0.044 = 3.41 × 10⁵ J kg⁻¹. Mark scheme (3 marks). C1: corrected mass. C1: L = E/m. C1: units.', 3, NULL, NULL),
('072b248b-0247-51ce-a456-ca5e62c2eeea', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 30, 30, 'Liquid nitrogen boils at 77 K with L_v = 2.0 × 10⁵ J kg⁻¹. A 25 W heater is placed in a flask of liquid nitrogen. Calculate the mass that boils away in 10 minutes.', NULL, 2, 'numeric'::answer_type, '0.075', 'kg', false, NULL, false, NULL, 'E = Pt = 25 × 600 = 15000 J. m = E/L = 15000 ÷ 2.0 × 10⁵ = 0.075 kg. Mark scheme (4 marks). C1: E = Pt. C1: m = E/L. C1: t in s. A1: m = 0.075 kg.', 4, NULL, NULL),
('9f83975e-33e8-565a-a615-47a6e9126604', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 31, 31, 'A temperature–time graph for a liquid cooling to a solid shows a horizontal section at 54 °C. What can be concluded?', NULL, 2, 'multiple_choice'::answer_type, 'The substance freezes at 54 °C, releasing latent heat that balances the loss to the surroundings', NULL, false, NULL, false, NULL, 'While freezing, the latent heat released keeps the temperature constant even though energy is still lost. Mark scheme (3 marks). C1: freezing point. C1: latent heat released. A1: B (The substance freezes at 54 °C, releasing latent heat that balances the loss to the surroundings).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg1782a2af-t fg1782a2af-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg1782a2af-t">Cooling curve</title><desc id="fg1782a2af-d">Temperature against time for a liquid cooling to a solid: the temperature falls, stays constant at 54 °C for a while, then falls again.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="112.4" y1="34" x2="112.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="195.4" y1="34" x2="195.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="278.3" y1="34" x2="278.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="361.3" y1="34" x2="361.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="195.8" x2="382" y2="195.8" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="149.6" x2="382" y2="149.6" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="103.3" x2="382" y2="103.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="57.1" x2="382" y2="57.1" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="29.4" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="29.4,24 32.4,30.3 26.5,30.3" style="fill:currentColor;stroke:none"/><line x1="29.4" y1="242" x2="29.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="112.4" y1="242" x2="112.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="112.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="195.4" y1="242" x2="195.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="195.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">8</text><line x1="278.3" y1="242" x2="278.3" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="278.3" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">12</text><line x1="361.3" y1="242" x2="361.3" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="361.3" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">16</text><line x1="25.4" y1="242" x2="29.4" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="25.4" y1="195.8" x2="29.4" y2="195.8" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="195.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">20</text><line x1="25.4" y1="149.6" x2="29.4" y2="149.6" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="149.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">40</text><line x1="25.4" y1="103.3" x2="29.4" y2="103.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="103.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">60</text><line x1="25.4" y1="57.1" x2="29.4" y2="57.1" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="57.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">80</text><text x="205.7" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">t / min</text><text x="25.4" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">θ / °C</text><line x1="29.4" y1="117.2" x2="382" y2="117.2" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><text x="380" y="107.2" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">54 °C</text><polyline points="29.4,57.1 112.4,117.2 278.3,117.2 361.3,172.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Temperature against time for a liquid cooling to a solid: the temperature falls, stays constant at 54 °C for a while, then falls again.'),
('4aaaeb64-265c-5b5b-bc1d-038e9ed84649', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 32, 32, 'A 500 W electric heater is used to vaporise water already at 100 °C. In 4.0 minutes the mass of water falls by 50 g. Calculate L_v from these results.', NULL, 2, 'numeric'::answer_type, '2.4e6', 'J kg⁻¹', false, NULL, false, NULL, 'E = Pt = 500 × 240 = 1.2 × 10⁵ J. L_v = E/m = 1.2 × 10⁵ ÷ 0.050 = 2.4 × 10⁶ J kg⁻¹. Mark scheme (3 marks). C1: E = Pt. C1: L = E/m. A1: L_v = 2.4 × 10⁶ J kg⁻¹.', 3, NULL, NULL),
('8e09ff6a-d65d-5324-86cd-3baaf1f022cc', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 33, 33, 'The value of L_v found in a simple heating experiment is usually larger than the accepted value. Why?', NULL, 2, 'multiple_choice'::answer_type, 'Some of the heater''s energy is lost to the surroundings, so less water boils than expected', NULL, false, NULL, false, NULL, 'Energy lost means the measured mass loss is too small for the energy counted, giving L = E/m too large. Mark scheme (3 marks). C1: energy lost. C1: m too small, L too large. A1: C (Some of the heater''s energy is lost to the surroundings, so less water boils than expected).', 3, NULL, NULL),
('658abb12-1340-5387-9447-49bc0fa7e84b', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 34, 34, 'Sweat evaporates from an athlete at 0.50 kg per hour. The latent heat of vaporisation of sweat at skin temperature is 2.4 × 10⁶ J kg⁻¹. Calculate the cooling power provided.', NULL, 2, 'numeric'::answer_type, '333.3', 'W', false, NULL, false, NULL, 'Energy per hour = 0.50 × 2.4 × 10⁶ = 1.2 × 10⁶ J. P = 1.2 × 10⁶ ÷ 3600 = 333 W. Mark scheme (4 marks). C1: E = mL. C1: per second. C1: P = E/t. A1: P = 333 W.', 4, NULL, NULL),
('18bb72d1-4b5e-5ade-8146-9c2cfadeb797', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 35, 35, 'An ice cube tray holds 0.30 kg of water at 0 °C. The freezer extracts energy at 40 W. How long does it take to freeze all the water? Take the specific latent heat of fusion of ice as 3.34 × 10⁵ J kg⁻¹.', NULL, 2, 'numeric'::answer_type, '2505', 's', false, NULL, false, NULL, 'E = mL = 0.30 × 3.34 × 10⁵ = 1.00 × 10⁵ J. t = E/P = 1.00 × 10⁵ ÷ 40 = 2500 s. Mark scheme (3 marks). C1: E = mL. C1: t = E/P. A1: t = 2500 s.', 3, NULL, NULL),
('a49bcf5d-316d-571b-a636-38873880fce5', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 36, 36, 'Why does a pressure cooker cook food faster?', NULL, 2, 'multiple_choice'::answer_type, 'Higher pressure raises the boiling point of the water, so the food is at a higher temperature', NULL, false, NULL, false, NULL, 'At about 2 atm water boils at about 120 °C, so the food cooks faster. Mark scheme (3 marks). C1: boiling point rises with pressure. C1: higher cooking temperature. A1: A (Higher pressure raises the boiling point of the water, so the food is at a higher temperature).', 3, NULL, NULL),
('df4d6b45-49ab-5a6e-9092-b8aaf9fd1919', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 37, 37, 'A 0.20 kg block of ice at 0 °C is dropped into 0.80 kg of water at 30 °C in an insulated flask. Calculate the energy the water can give up in cooling to 0 °C, and decide whether all the ice melts. Give that energy. Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹. Take the specific latent heat of fusion of ice as 3.34 × 10⁵ J kg⁻¹.', NULL, 2, 'numeric'::answer_type, '1.008e5', 'J', false, NULL, false, NULL, 'Energy available = 0.80 × 4200 × 30 = 1.01 × 10⁵ J. Energy to melt the ice = 0.20 × 3.34 × 10⁵ = 6.68 × 10⁴ J. Available > needed, so all the ice melts. Mark scheme (4 marks). C1: mcΔθ for water. C1: mL for ice. B1: comparison. A1: E = 1.01 × 10⁵ J.', 4, NULL, NULL),
('874c5638-e6e5-5153-b95d-b3b696b1b164', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 38, 38, 'An electric heater raises 0.20 kg of a solid to its melting point and then melts it, using 1.04 × 10⁵ J in total. The heating to the melting point needed 3.6 × 10⁴ J. Calculate the specific latent heat of fusion.', NULL, 2, 'numeric'::answer_type, '3.4e5', 'J kg⁻¹', false, NULL, false, NULL, 'Energy to melt = 1.04 × 10⁵ − 3.6 × 10⁴ = 6.8 × 10⁴ J. L = 6.8 × 10⁴ ÷ 0.20 = 3.4 × 10⁵ J kg⁻¹. Mark scheme (3 marks). C1: subtract heating energy. C1: L = E/m. A1: L = 3.4 × 10⁵ J kg⁻¹.', 3, NULL, NULL),
('9701eddc-fdb8-5ec9-ab76-bef9188cba69', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 39, 39, 'A 0.25 kg aluminium pan (c = 900 J kg⁻¹ K⁻¹) containing 0.50 kg of water at 100 °C is on a 1.8 kW hob. Ignoring losses, how long does it take to boil away 0.10 kg of the water? Take the specific latent heat of vaporisation of water as 2.26 × 10⁶ J kg⁻¹.', NULL, 2, 'numeric'::answer_type, '125.6', 's', false, NULL, false, NULL, 'Pan and water are already at 100 °C, so all the energy boils water: E = mL_v = 0.10 × 2.26 × 10⁶ = 2.26 × 10⁵ J, t = E/P = 2.26 × 10⁵ ÷ 1800 = 126 s. Mark scheme (3 marks). B1: pan needs no heating. C1: E = mL_v. C1: t = E/P.', 3, NULL, NULL),
('f56abcf9-d36e-59e6-b335-dc3caa2796c6', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 40, 40, '0.050 kg of ice at −15 °C is put into a glass containing 0.25 kg of lemonade (treat as water) at 24 °C. Ignore the glass and surroundings. c_ice = 2100 J kg⁻¹ K⁻¹. (a) Calculate the energy needed to warm the ice to 0 °C and melt it. (b) Write an equation for the final temperature θ. (c) Calculate θ. Give only the answer to (c). Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹. Take the specific latent heat of fusion of ice as 3.34 × 10⁵ J kg⁻¹.', NULL, 3, 'numeric'::answer_type, '5.496', '°C', false, NULL, false, NULL, '(a) 0.050 × 2100 × 15 + 0.050 × 3.34 × 10⁵ = 1580 + 1.67 × 10⁴ = 1.83 × 10⁴ J. (b) Energy lost by lemonade = energy gained by ice: 0.25 × 4200 × (24 − θ) = 1.828 × 10⁴ + 0.050 × 4200 × θ. (c) 25200 − 1050θ = 1.828 × 10⁴ + 210θ, so θ = (25200 − 1.828 × 10⁴) ÷ 1260 = 5.50 °C. Mark scheme (6 marks). C1: ice warming. C1: ice melting. A1: total for (a). M1: energy balance including melted ice warming. C1: rearranged. A1: θ = 5.50 °C.', 6, NULL, NULL),
('1425b535-6f68-5981-8e27-d0a202289596', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 41, 41, 'A 3.0 kW kettle holds 1.2 kg of water at 20 °C. (a) Calculate the time to bring it to 100 °C. (b) The kettle is left on for a further 2.0 minutes. Calculate the mass of water boiled away. (c) Suggest why the real mass lost is a little less. Give only the answer to (b). Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹. Take the specific latent heat of vaporisation of water as 2.26 × 10⁶ J kg⁻¹.', NULL, 3, 'numeric'::answer_type, '0.1593', 'kg', false, NULL, false, NULL, '(a) E = mcΔθ = 1.2 × 4200 × 80 = 4.03 × 10⁵ J, t = E/P = 4.03 × 10⁵ ÷ 3000 = 134 s. (b) E = Pt = 3000 × 120 = 3.6 × 10⁵ J, m = E/L_v = 3.6 × 10⁵ ÷ 2.26 × 10⁶ = 0.159 kg. (c) Some energy is lost to the surroundings and the kettle body, so less is available to boil water. Mark scheme (5 marks). C1: mcΔθ. A1: t. C1: E = Pt. A1: m = 0.159 kg. B1: energy losses.', 5, NULL, NULL),
('073cd252-d7aa-5a8e-87a2-0023a75b8f23', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 42, 42, 'A student heats 0.40 kg of a solid wax at a steady 50 W and records its temperature every minute: 20, 32, 44, 52, 52, 52, 52, 52, 60, 68 °C at t = 0, 1, …, 9 min. (a) State the melting point. (b) Use the time the temperature is constant to calculate L_f. (c) Use the first three minutes to calculate the specific heat capacity of the solid wax. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '37500', 'J kg⁻¹', false, NULL, false, NULL, '(a) 52 °C. (b) Constant from about t = 3 to t = 8 min: 5 minutes. E = Pt = 50 × 300 = 15000 J, L = E/m = 15000 ÷ 0.40 = 3.75 × 10⁴ J kg⁻¹. (c) In 2 min (120 s) the temperature rises 24 K: c = Pt/(mΔθ) = 50 × 120 ÷ (0.40 × 24) = 625 J kg⁻¹ K⁻¹. Mark scheme (6 marks). B1: 52 °C. C1: duration of plateau. C1: E = Pt. A1: L. C1: c = Pt/mΔθ. A1: L = 3.75 × 10⁴ J kg⁻¹.', 6, NULL, NULL),
('c3f1f683-9b26-51eb-a8b2-f27a1c8e6b44', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 43, 43, 'A climber melts snow at −8.0 °C to make 1.5 kg of water at 60 °C for tea, using a gas stove. c_ice = 2100 J kg⁻¹ K⁻¹. (a) Calculate the energy to warm the snow to 0 °C. (b) Calculate the total energy needed. (c) Only 40 % of the stove''s energy reaches the pan. Calculate the energy the gas must release. Give only the answer to (c). Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹. Take the specific latent heat of fusion of ice as 3.34 × 10⁵ J kg⁻¹.', NULL, 3, 'numeric'::answer_type, '2.26e6', 'J', false, NULL, false, NULL, '(a) 1.5 × 2100 × 8.0 = 2.52 × 10⁴ J. (b) + 1.5 × 3.34 × 10⁵ + 1.5 × 4200 × 60: total = 9.04 × 10⁵ J. (c) E = 9.042 × 10⁵ ÷ 0.40 = 2.26 × 10⁶ J. Mark scheme (5 marks). A1: warming snow. C1: melting. C1: warming water. A1: total. A1: E = 2.26 × 10⁶ J.', 5, NULL, NULL),
('b2955819-4e54-5492-b4e3-a12564f01adf', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 44, 44, 'Boiling water in an insulated flask is kept at 100 °C by an electric heater, and the rate of mass loss is measured. At 120 W the mass decreases at 4.6 × 10⁻⁵ kg s⁻¹; at 200 W it decreases at 8.2 × 10⁻⁵ kg s⁻¹. (a) Explain why two powers are used. (b) Write P = L_v(dm/dt) + h for each, where h is the rate of heat loss. (c) Solve for L_v. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2.222e6', 'J kg⁻¹', false, NULL, false, NULL, '(a) Heat is lost to the surroundings at a rate h that is the same at both powers (same temperature), so it can be eliminated. (b) 120 = L_v × 4.6 × 10⁻⁵ + h and 200 = L_v × 8.2 × 10⁻⁵ + h. (c) Subtracting: 80 = L_v × 3.6 × 10⁻⁵, L_v = 80 ÷ 3.6 × 10⁻⁵ = 2.22 × 10⁶ J kg⁻¹. Mark scheme (6 marks). B1: losses the same at the same temperature. B1: eliminate h. C1: two equations. M1: subtract. C1: rearranged. A1: L_v = 2.22 × 10⁶ J kg⁻¹.', 6, NULL, NULL),
('b939bcae-c56b-5c2f-8ec6-1e61e07aa267', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 45, 45, 'A 0.040 kg ice cube at 0 °C is placed in 0.20 kg of water at 30 °C in an insulated cup. (a) Calculate the energy needed to melt the ice. (b) Show that all the ice melts. (c) Calculate the final temperature. Give only the answer to (c). Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹. Take the specific latent heat of fusion of ice as 3.34 × 10⁵ J kg⁻¹.', NULL, 3, 'numeric'::answer_type, '11.75', '°C', false, NULL, false, NULL, '(a) 0.040 × 3.34 × 10⁵ = 1.34 × 10⁴ J. (b) The water can give 0.20 × 4200 × 30 = 2.52 × 10⁴ J cooling to 0 °C — more than needed. (c) 0.20 × 4200 × (30 − θ) = 1.336 × 10⁴ + 0.040 × 4200 × θ: θ = (25200 − 1.336 × 10⁴) ÷ 1008 = 11.7 °C. Mark scheme (5 marks). A1: energy to melt. B1: comparison. M1: energy balance. C1: includes warming of melted ice. A1: θ = 11.7 °C.', 5, NULL, NULL),
('960d8bc1-57b0-5640-b79b-f7f93d704282', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 46, 46, 'An ice rink is cooled by pipes carrying cold brine. A 5.0 cm layer of water at 0 °C over a 30 m × 60 m rink (water density 1000 kg m⁻³) must be frozen. (a) Calculate the mass of water. (b) Calculate the energy to be removed. (c) The refrigeration plant removes energy at 250 kW. Calculate the time taken, in hours. Give only the answer to (c). Take the specific latent heat of fusion of ice as 3.34 × 10⁵ J kg⁻¹.', NULL, 3, 'numeric'::answer_type, '33.4', 'h', false, NULL, false, NULL, '(a) V = 30 × 60 × 0.050 = 90 m³, m = 9.0 × 10⁴ kg. (b) E = mL = 9.0 × 10⁴ × 3.34 × 10⁵ = 3.01 × 10¹⁰ J. (c) t = E/P = 3.006 × 10¹⁰ ÷ 2.5 × 10⁵ = 1.20 × 10⁵ s. In hours: 1.202 × 10⁵ ÷ 3600 = 33.4. Mark scheme (6 marks). C1: volume. A1: mass. C1: E = mL. A1: E. C1: t = E/P. A1: t = 33.4 h.', 6, NULL, NULL),
('aa46e425-efb3-5bec-93cd-41680c59fea7', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 47, 47, 'A student finds the specific latent heat of vaporisation by boiling water with a 1.0 kW kettle on a balance. The mass falls from 1.234 kg to 1.138 kg in 4.0 minutes once boiling. (a) Calculate the mass boiled away. (b) Calculate L_v. (c) Explain why the result is too high and suggest an improvement. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2.5e6', 'J kg⁻¹', false, NULL, false, NULL, '(a) 1.234 − 1.138 = 0.096 kg. (b) L_v = Pt/m = 1000 × 240 ÷ 0.096 = 2.50 × 10⁶ J kg⁻¹. (c) Some energy is lost to the surroundings, so less water boils than the energy suggests; insulate the kettle, or use two powers to eliminate the losses. Mark scheme (5 marks). A1: mass. C1: E = Pt. A1: L_v = 2.50 × 10⁶ J kg⁻¹. B1: losses make L too large. B1: improvement.', 5, NULL, NULL),
('ffa0613a-4288-5cc7-b1d2-82bdaf07d796', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 48, 48, 'Molten aluminium at its melting point (660 °C) is poured into a mould and solidifies, then cools to 20 °C. Mass 2.0 kg, L_f = 3.97 × 10⁵ J kg⁻¹, c = 900 J kg⁻¹ K⁻¹. (a) Calculate the energy released on solidifying. (b) Calculate the energy released on cooling. (c) Calculate the total. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.946e6', 'J', false, NULL, false, NULL, '(a) 2.0 × 3.97 × 10⁵ = 7.94 × 10⁵ J. (b) 2.0 × 900 × 640 = 1.15 × 10⁶ J. (c) 7.940 × 10⁵ + 1.152 × 10⁶ = 1.95 × 10⁶ J. Mark scheme (5 marks). C1: mL. A1: (a). C1: mcΔθ with Δθ = 640 K. A1: (b). A1: E = 1.95 × 10⁶ J.', 5, NULL, NULL),
('4572f6f5-14a3-592c-b097-bceef398414c', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 49, 49, 'A heater supplies energy at a constant rate to 0.30 kg of a substance that starts as a solid. Its temperature rises from 20 °C to 80 °C in 120 s, stays at 80 °C for 300 s, then rises again. The specific heat capacity of the solid is 1500 J kg⁻¹ K⁻¹. (a) Calculate the power of the heater. (b) Calculate the specific latent heat of fusion. (c) State one assumption made. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2.25e5', 'J kg⁻¹', false, NULL, false, NULL, '(a) P = mcΔθ/t = 0.30 × 1500 × 60 ÷ 120 = 225 W. (b) L = Pt/m = 225 × 300 ÷ 0.30 = 2.25 × 10⁵ J kg⁻¹. (c) No energy is lost to the surroundings (or the heater power is constant). Mark scheme (6 marks). C1: energy for temperature rise. A1: P. C1: E = Pt for plateau. C1: L = E/m. A1: L = 2.25 × 10⁵ J kg⁻¹. B1: assumption.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgdf0bd378-t fgdf0bd378-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgdf0bd378-t">Heating curve</title><desc id="fgdf0bd378-d">Temperature against time: the solid warms from 20 °C to 80 °C in 120 s, stays at 80 °C for 300 s while it melts, then the liquid warms again.</desc><line x1="36.2" y1="34" x2="36.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="105.3" y1="34" x2="105.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="174.5" y1="34" x2="174.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="243.7" y1="34" x2="243.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.8" y1="34" x2="312.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="207.3" x2="382" y2="207.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="172.7" x2="382" y2="172.7" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="138" x2="382" y2="138" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="103.3" x2="382" y2="103.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="68.7" x2="382" y2="68.7" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="242" x2="36.2" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="36.2,24 39.1,30.3 33.2,30.3" style="fill:currentColor;stroke:none"/><line x1="36.2" y1="242" x2="36.2" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="36.2" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="105.3" y1="242" x2="105.3" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="105.3" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">100</text><line x1="174.5" y1="242" x2="174.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="174.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">200</text><line x1="243.7" y1="242" x2="243.7" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="243.7" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">300</text><line x1="312.8" y1="242" x2="312.8" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="312.8" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">400</text><line x1="382" y1="242" x2="382" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">500</text><line x1="32.2" y1="242" x2="36.2" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="32.2" y1="207.3" x2="36.2" y2="207.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="207.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">20</text><line x1="32.2" y1="172.7" x2="36.2" y2="172.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="172.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">40</text><line x1="32.2" y1="138" x2="36.2" y2="138" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="138" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">60</text><line x1="32.2" y1="103.3" x2="36.2" y2="103.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="103.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">80</text><line x1="32.2" y1="68.7" x2="36.2" y2="68.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="68.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">100</text><text x="209.1" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">t / s</text><text x="32.2" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">θ / °C</text><polyline points="36.2,207.3 119.2,103.3 326.7,103.3 368.2,51.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Temperature against time: the solid warms from 20 °C to 80 °C in 120 s, stays at 80 °C for 300 s while it melts, then the liquid warms again.'),
('2b0d9220-ae37-51f1-8d81-b182c25d778a', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '608a3093-aba0-4a7e-ade8-3b518d43db3b', 'a-level', '19.1', '9702 coursebook 19.1 · Changes of state', 50, 50, 'A person loses 2.4 × 10⁶ J kg⁻¹ of energy for each kg of sweat evaporated. During a run she produces 900 W of heat, and 70 % must be removed by sweating. (a) Calculate the cooling power from sweating. (b) Calculate the mass of sweat evaporated in 1.0 hour. (c) Explain why sweating is less effective in humid air. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.945', 'kg', false, NULL, false, NULL, '(a) 0.70 × 900 = 630 W. (b) m = Pt/L = 630 × 3600 ÷ 2.4 × 10⁶ = 0.945 kg. (c) In humid air fewer water molecules escape from the skin (more return), so the net rate of evaporation — and cooling — is lower. Mark scheme (5 marks). A1: 630 W. C1: E = Pt. C1: m = E/L. A1: m = 0.945 kg. B1: humid air reduces net evaporation.', 5, NULL, NULL)
