('2ff3c25b-df90-53b7-b1d0-7ab3f868fc77', '7b9e89fa-f991-5392-a6a9-3e539d9e8327', 'The escape of the most energetic molecules from the surface of a liquid at any temperature', 'D', true, 3),
('2c5066d9-8112-5962-8e02-d08395dda44f', '673cef50-0d2a-5a29-bc09-322f6e5cb5d8', 'The liquid absorbs energy from the air', 'A', false, 0),
('555cea3d-bd9d-51e0-b01a-5b21572a5bbe', '673cef50-0d2a-5a29-bc09-322f6e5cb5d8', 'The fastest molecules leave, so the mean kinetic energy of those left decreases', 'B', true, 1),
('3b518f01-e27a-5488-90d8-fa1d86d59ebc', '673cef50-0d2a-5a29-bc09-322f6e5cb5d8', 'The molecules left behind gain potential energy', 'C', false, 2),
('a3b1d3d9-549d-5d1f-ad75-4c4aaa8b73b4', '673cef50-0d2a-5a29-bc09-322f6e5cb5d8', 'The pressure above the liquid rises', 'D', false, 3),
('c4b7d5c4-6252-572d-88ee-5414a3dfad2d', 'd09f7798-fec8-530b-a003-8acd13392f8f', 'The energy needed to raise 1 kg of liquid by 1 K', 'A', false, 0),
