('817b49de-83a7-5d3a-b0a7-79cf53b58c88', 'a5f5e11e-ec2c-5fa2-a935-857481edd7b7', 'To subtract the ice melted by energy from the room, so only the heater''s energy is counted', 'D', true, 3),
('a80ab1ea-16a6-54da-a802-48cd4608263e', '9f83975e-33e8-565a-a615-47a6e9126604', 'The substance has stopped losing energy', 'A', false, 0),
('0dd3dae9-2e55-506d-89b4-83efd02f7097', '9f83975e-33e8-565a-a615-47a6e9126604', 'The substance freezes at 54 °C, releasing latent heat that balances the loss to the surroundings', 'B', true, 1),
('0ab264ec-dac0-5b1c-a8c9-ce8d78749cbe', '9f83975e-33e8-565a-a615-47a6e9126604', 'The specific heat capacity becomes infinite', 'C', false, 2),
('03b465e1-3f46-5b62-b786-f0220408e609', '9f83975e-33e8-565a-a615-47a6e9126604', 'The thermometer has failed', 'D', false, 3),
('03cb876d-17fc-5105-b131-2e2d2b8e3016', '8e09ff6a-d65d-5324-86cd-3baaf1f022cc', 'The thermometer reads too high', 'A', false, 0),
('39c55300-b091-54a8-b4ac-c37b6d530bc5', '8e09ff6a-d65d-5324-86cd-3baaf1f022cc', 'Water has a low specific heat capacity', 'B', false, 1),
('3d83b01b-1464-5afd-bae2-7d429abdbef4', '8e09ff6a-d65d-5324-86cd-3baaf1f022cc', 'Some of the heater''s energy is lost to the surroundings, so less water boils than expected', 'C', true, 2),
('df89ec06-ae6c-5bbc-95b6-5a2dc2404edb', '8e09ff6a-d65d-5324-86cd-3baaf1f022cc', 'Steam condenses back into the beaker', 'D', false, 3),
('d2135dff-6ad1-544b-a2a4-646f33bafd72', 'a49bcf5d-316d-571b-a636-38873880fce5', 'Higher pressure raises the boiling point of the water, so the food is at a higher temperature', 'A', true, 0),
('4e1d9fda-83cc-5a9b-aa5d-a6b3cb5b59a9', 'a49bcf5d-316d-571b-a636-38873880fce5', 'It lowers the latent heat', 'B', false, 1),
('b81785a4-8f23-595f-ae28-0401bb8daaa5', 'a49bcf5d-316d-571b-a636-38873880fce5', 'Steam is cooler under pressure', 'C', false, 2),
('920a454a-930c-5c2a-8734-251b841ac271', 'a49bcf5d-316d-571b-a636-38873880fce5', 'It reduces the specific heat capacity', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('338a46b3-0a80-5d32-8caa-34bb8ae2b886', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 9, 9, 'In ΔU = q + w, what does q represent?', NULL, 1, 'multiple_choice'::answer_type, 'The energy transferred to the system by heating', NULL, false, NULL, false, NULL, 'q is the thermal energy supplied to the system; w is the work done on it; ΔU is the increase in internal energy. Mark scheme (1 mark). B1: C (The energy transferred to the system by heating).', 1, NULL, NULL),
('c28135a9-e86f-5c59-afc5-74e61d3d49ed', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 10, 10, 'A gas expands and does work on its surroundings. In ΔU = q + w, what is the sign of w?', NULL, 1, 'multiple_choice'::answer_type, 'Negative', NULL, false, NULL, false, NULL, 'w is the work done ON the gas. When the gas expands it does work on the surroundings, so w is negative. Mark scheme (1 mark). B1: A (Negative).', 1, NULL, NULL),
('92f0d16c-5e9e-51c3-a2c4-411a482ee12d', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 11, 11, 'A gas is heated with 750 J of energy and 300 J of work is done on it. Calculate the increase in its internal energy.', NULL, 1, 'numeric'::answer_type, '1050', 'J', false, NULL, false, NULL, 'ΔU = q + w = 750 + 300 = 1050 J. Mark scheme (2 marks). C1: ΔU = q + w with signs. A1: ΔU = 1050 J.', 2, NULL, NULL),
('50be3722-e239-53b2-b41f-881ea586b2e8', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 12, 12, 'A gas absorbs 400 J by heating while doing 150 J of work on its surroundings. Calculate ΔU.', NULL, 1, 'numeric'::answer_type, '250', 'J', false, NULL, false, NULL, 'w = −150 J. ΔU = q + w = 400 + (−150) = 250 J. Mark scheme (2 marks). C1: w negative for work done by gas. A1: ΔU = 250 J.', 2, NULL, NULL),
('caf3e110-a2fb-51a5-9cf0-2ff300776587', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 13, 13, 'A gas expands at a constant pressure of 2.0 × 10⁵ Pa, increasing its volume by 3.0 × 10⁻³ m³. Calculate the work done by the gas.', NULL, 1, 'numeric'::answer_type, '600', 'J', false, NULL, false, NULL, 'W = pΔV = 2.0 × 10⁵ × 3.0 × 10⁻³ = 600 J. Mark scheme (2 marks). C1: W = pΔV. A1: W = 600 J.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgadc4f787-t fgadc4f787-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgadc4f787-t">Expansion at constant pressure</title><desc id="fgadc4f787-d">p–V graph: a horizontal line at 2.0 × 10⁵ Pa as the volume increases by 3.0 × 10⁻³ m³. The shaded rectangle under the line is the work done by the gas.</desc><line x1="102.8" y1="34" x2="102.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.2" y1="34" x2="312.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="202" x2="382" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="162" x2="382" y2="162" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="122" x2="382" y2="122" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="82" x2="382" y2="82" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="42" x2="382" y2="42" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="33" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="33,24 36,30.3 30.1,30.3" style="fill:currentColor;stroke:none"/><line x1="102.8" y1="242" x2="102.8" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102.8" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">V₁</text><line x1="312.2" y1="242" x2="312.2" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="312.2" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">V₁ + 3.0 × 10⁻³ m³</text><line x1="29" y1="242" x2="33" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="29" y1="202" x2="33" y2="202" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="202" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.5</text><line x1="29" y1="162" x2="33" y2="162" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="162" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.0</text><line x1="29" y1="122" x2="33" y2="122" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="122" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.5</text><line x1="29" y1="82" x2="33" y2="82" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="82" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2.0</text><line x1="29" y1="42" x2="33" y2="42" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="42" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2.5</text><text x="207.5" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">V</text><text x="29" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">p / 10⁵ Pa</text><polygon points="102.8,82 312.2,82 312.2,242 102.8,242" style="stroke:none;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><polyline points="102.8,82 312.2,82" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'p–V graph: a horizontal line at 2.0 × 10⁵ Pa as the volume increases by 3.0 × 10⁻³ m³. The shaded rectangle under the line is the work done by the gas.'),
('e573e40d-7c6d-56eb-8727-f3b04a3f2237', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 14, 14, 'Which principle does the first law of thermodynamics express?', NULL, 1, 'multiple_choice'::answer_type, 'Conservation of energy', NULL, false, NULL, false, NULL, 'The increase in internal energy equals the energy supplied by heating plus the work done on the system. Mark scheme (1 mark). B1: D (Conservation of energy).', 1, NULL, NULL),
('1c9761f4-4e7d-5c98-8c26-5bdee2b3c1bf', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 15, 15, 'A bicycle pump does 80 J of work compressing the air inside it so quickly that no heat escapes. What is the change in internal energy of the air?', NULL, 1, 'numeric'::answer_type, '80', 'J', false, NULL, false, NULL, 'q = 0, w = +80 J, so ΔU = 0 + 80 = 80 J (the air warms up). Mark scheme (2 marks). C1: q = 0. A1: ΔU = 80 J.', 2, NULL, NULL),
('d985c998-a639-5656-b928-d7ae16c94640', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 16, 16, 'A gas expands without any heat entering or leaving (adiabatically). What happens to its internal energy?', NULL, 1, 'multiple_choice'::answer_type, 'It decreases, because the gas does work', NULL, false, NULL, false, NULL, 'q = 0 and w < 0, so ΔU = w < 0: the gas cools. Mark scheme (1 mark). B1: B (It decreases, because the gas does work).', 1, NULL, NULL),
('bd755c31-a2ea-597b-aeaa-5922e9918de2', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 17, 17, 'Calculate the work done on a gas when it is compressed at a constant pressure of 1.2 × 10⁵ Pa from 4.0 × 10⁻³ m³ to 2.5 × 10⁻³ m³.', NULL, 1, 'numeric'::answer_type, '180', 'J', false, NULL, false, NULL, 'W = pΔV = 1.2 × 10⁵ × (4.0 − 2.5) × 10⁻³ = 180 J done on the gas. Mark scheme (2 marks). C1: W = p × volume decrease. A1: W = 180 J.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg82181785-t fg82181785-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg82181785-t">Compression at constant pressure</title><desc id="fg82181785-d">p–V graph: a horizontal line at 1.2 × 10⁵ Pa from 4.0 × 10⁻³ m³ to 2.5 × 10⁻³ m³; the shaded area is the work done on the gas.</desc><line x1="33" y1="34" x2="33" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="102.8" y1="34" x2="102.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="172.6" y1="34" x2="172.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="242.4" y1="34" x2="242.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.2" y1="34" x2="312.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="190" x2="382" y2="190" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="138" x2="382" y2="138" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="86" x2="382" y2="86" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="33" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="33,24 36,30.3 30.1,30.3" style="fill:currentColor;stroke:none"/><line x1="33" y1="242" x2="33" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="33" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="102.8" y1="242" x2="102.8" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102.8" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1</text><line x1="172.6" y1="242" x2="172.6" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="172.6" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2</text><line x1="242.4" y1="242" x2="242.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="242.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3</text><line x1="312.2" y1="242" x2="312.2" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="312.2" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="382" y1="242" x2="382" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">5</text><line x1="29" y1="242" x2="33" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="29" y1="190" x2="33" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="190" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.4</text><line x1="29" y1="138" x2="33" y2="138" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="138" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.8</text><line x1="29" y1="86" x2="33" y2="86" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="86" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.2</text><line x1="29" y1="34" x2="33" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.6</text><text x="207.5" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">V / 10⁻³ m³</text><text x="29" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">p / 10⁵ Pa</text><polygon points="207.5,86 312.2,86 312.2,242 207.5,242" style="stroke:none;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><polyline points="312.2,86 207.5,86" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'p–V graph: a horizontal line at 1.2 × 10⁵ Pa from 4.0 × 10⁻³ m³ to 2.5 × 10⁻³ m³; the shaded area is the work done on the gas.'),
('f420e4f4-59c0-5f11-81f2-4802b6c64e9a', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 18, 18, 'An ideal gas is taken round a complete cycle back to its starting state. What is the total change in its internal energy?', NULL, 1, 'multiple_choice'::answer_type, 'Zero', NULL, false, NULL, false, NULL, 'Internal energy depends only on the state (for an ideal gas, only on temperature). Back at the start, ΔU = 0. Mark scheme (1 mark). B1: C (Zero).', 1, NULL, NULL),
('bb4b831e-43e5-5997-be05-99a2e9f78764', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 19, 19, 'A gas loses 500 J by heating to its surroundings while 200 J of work is done on it. Calculate ΔU.', NULL, 1, 'numeric'::answer_type, '-300', 'J', false, NULL, true, NULL, 'q = −500 J, w = +200 J. ΔU = −500 + 200 = −300 J. Mark scheme (2 marks). C1: signs of q and w. A1: ΔU = −300 J.', 2, NULL, NULL),
('2930deb0-42cd-58c0-b70b-8fa656d14a45', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 20, 20, 'For an ideal gas kept at constant temperature, what is ΔU?', NULL, 1, 'multiple_choice'::answer_type, 'Zero', NULL, false, NULL, false, NULL, 'The internal energy of an ideal gas depends only on its temperature, so at constant temperature ΔU = 0 and q = −w. Mark scheme (1 mark). B1: A (Zero).', 1, NULL, NULL),
('defdeb52-a110-5e8a-a960-434bebf1366a', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 21, 21, 'A gas at constant temperature does 350 J of work as it expands. How much energy was supplied to it by heating?', NULL, 1, 'numeric'::answer_type, '350', 'J', false, NULL, false, NULL, 'ΔU = 0, so q = −w = −(−350) = 350 J. Mark scheme (2 marks). C1: ΔU = 0 at constant T. A1: q = 350 J.', 2, NULL, NULL),
('b489d5c9-a308-5461-b2e3-5f725273dcd3', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 22, 22, 'Which unit is correct for pΔV?', NULL, 1, 'multiple_choice'::answer_type, 'J', NULL, false, NULL, false, NULL, 'Pa × m³ = N m⁻² × m³ = N m = J. Mark scheme (1 mark). B1: D (J).', 1, NULL, NULL),
('42588615-507d-5698-8509-b4e2e3605280', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 23, 23, 'A gas in a cylinder expands at a pressure of 1.0 × 10⁵ Pa. The piston of area 0.020 m² moves out 0.15 m. Calculate the work done by the gas.', NULL, 1, 'numeric'::answer_type, '300', 'J', false, NULL, false, NULL, 'ΔV = A × d = 0.020 × 0.15 = 3.0 × 10⁻³ m³. W = pΔV = 1.0 × 10⁵ × 3.0 × 10⁻³ = 300 J. Mark scheme (2 marks). C1: ΔV = Ad, W = pΔV. A1: W = 300 J.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 300" role="img" aria-labelledby="fgc5627f08-t fgc5627f08-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgc5627f08-t">Gas pushing a piston out</title><desc id="fgc5627f08-d">Gas at 1.0 × 10⁵ Pa in a cylinder pushes a piston of area 0.020 m² outwards through 0.15 m.</desc><line x1="100" y1="60" x2="100" y2="270" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="220" y1="60" x2="220" y2="270" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100" y1="270" x2="220" y2="270" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="102" y="142" width="116" height="126" rx="0" style="stroke:none;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="102" y="130" width="116" height="12" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-muted,#6b7280);stroke-linecap:round;stroke-linejoin:round"/><text x="160" y="206" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">gas</text><text x="160" y="288" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">piston area 0.020 m²</text><text x="160" y="40" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">gas at 1.0 × 10⁵ Pa; piston moves out 0.15 m</text></svg>', 'Gas at 1.0 × 10⁵ Pa in a cylinder pushes a piston of area 0.020 m² outwards through 0.15 m.'),
('a9feb623-69b2-5afe-8a28-be8d3a40a165', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 24, 24, 'A balloon of air is placed in a freezer. Its volume decreases and it loses energy by heating. Which is correct?', NULL, 1, 'multiple_choice'::answer_type, 'q is negative and w is positive', NULL, false, NULL, false, NULL, 'Energy leaves by heating (q < 0); the surroundings do work compressing the air (w > 0). Mark scheme (1 mark). B1: B (q is negative and w is positive).', 1, NULL, NULL),
('a6a14ec8-9a67-5bbc-8d9b-c6c72f85f4a5', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 25, 25, 'A gas is heated with 1.2 kJ of energy at constant volume. Calculate the increase in its internal energy.', NULL, 1, 'numeric'::answer_type, '1200', 'J', false, NULL, false, NULL, 'At constant volume no work is done (w = 0), so ΔU = q + w = 1200 + 0 = 1200 J. Mark scheme (2 marks). C1: w = 0 at constant volume. A1: ΔU = 1200 J.', 2, NULL, NULL),
('eb4e41ed-6910-5ec6-9e25-4b87791d47a9', '732e83dd-2c22-497f-8d64-2f7a3fd69629', 'ac0eb546-c37c-5122-8eaa-89bbcb42a5c1', 'a-level', '19.2', '9702 coursebook 19.2 · The first law of thermodynamics', 26, 26, 'A gas at a constant pressure of 1.5 × 10⁵ Pa is heated with 900 J and expands from 2.0 × 10⁻³ m³ to 4.0 × 10⁻³ m³. Calculate the change in its internal energy.', NULL, 2, 'numeric'::answer_type, '600', 'J', false, NULL, false, NULL, 'Work done by gas = pΔV = 1.5 × 10⁵ × 2.0 × 10⁻³ = 300 J, so w = −300 J. ΔU = q + w = 900 − 300 = 600 J. Mark scheme (3 marks). C1: pΔV. C1: w negative. C1: ΔU = q + w.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg3bd92ad3-t fg3bd92ad3-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3bd92ad3-t">Expansion at constant pressure</title><desc id="fg3bd92ad3-d">p–V graph: a horizontal line at 1.5 × 10⁵ Pa from 2.0 × 10⁻³ m³ to 4.0 × 10⁻³ m³; the shaded area is the work done by the gas.</desc><line x1="33" y1="34" x2="33" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="102.8" y1="34" x2="102.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="172.6" y1="34" x2="172.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="242.4" y1="34" x2="242.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.2" y1="34" x2="312.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:roun