" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="91.2" y1="242" x2="91.2" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="91.2" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.5</text><line x1="149.4" y1="242" x2="149.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="149.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0</text><line x1="207.5" y1="242" x2="207.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="207.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.5</text><line x1="265.7" y1="242" x2="265.7" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="265.7" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0</text><line x1="323.8" y1="242" x2="323.8" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="323.8" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.5</text><line x1="382" y1="242" x2="382" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.0</text><line x1="29" y1="242" x2="33" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="29" y1="202" x2="33" y