INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('ba469cd4-7094-58ba-8542-014591f56b9d', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 9, 9, 'What is the internal energy of a substance?', NULL, 1, 'multiple_choice'::answer_type, 'The sum of the random kinetic and potential energies of all its molecules', NULL, false, NULL, false, NULL, 'Internal energy is the total of the randomly distributed microscopic kinetic and potential energies. Mark scheme (1 mark). B1: C (The sum of the random kinetic and potential energies of all its molecules).', 1, NULL, NULL),
('946751f9-5cc4-5a42-8fd7-729759f08bf4', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 10, 10, 'Why is the internal energy of an ideal gas only kinetic energy?', NULL, 1, 'multiple_choice'::answer_type, 'There are no forces between the molecules, so they have no potential energy', NULL, false, NULL, false, NULL, 'In an ideal gas, intermolecular forces are assumed zero (except in collisions), so Ep = 0. Mark scheme (1 mark). B1: A (There are no forces between the molecules, so they have no potential energy).', 1, NULL, NULL),
('e65b1296-7591-533c-9289-1356d7efaff7', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 11, 11, 'A block of ice melts at 0 °C. What happens to its internal energy?', NULL, 1, 'multiple_choice'::answer_type, 'It increases, because the molecular potential energy increases', NULL, false, NULL, false, NULL, 'Energy is supplied to break bonds; the potential energy rises while the kinetic energy (temperature) is unchanged. Mark scheme (1 mark). B1: D (It increases, because the molecular potential energy increases).', 1, NULL, NULL),
('7452a050-6ec0-527f-9e14-801827203536', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 12, 12, 'Which change increases the internal energy of a gas?', NULL, 1, 'multiple_choice'::answer_type, 'Heating it at constant volume', NULL, false, NULL, false, NULL, 'Heating at constant volume: ΔU = q > 0. Mark scheme (1 mark). B1: B (Heating it at constant volume).', 1, NULL, NULL),
('7698a9b3-8e30-5821-9c83-5ecfb8139100', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 13, 13, 'The internal energy of a monatomic ideal gas is U = (3/2)nRT. Calculate U for 1.5 mol at 300 K. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '5609', 'J', false, NULL, false, NULL, 'U = 1.5 × 1.5 × 8.31 × 300 = 5610 J. Mark scheme (2 marks). C1: U = (3/2)nRT. A1: U = 5610 J.', 2, NULL, NULL),
('79434e48-cfbd-5f05-b475-1359cf0bbd01', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 14, 14, '3.0 mol of helium (monatomic) is heated from 280 K to 330 K. Calculate the increase in its internal energy. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '1870', 'J', false, NULL, false, NULL, 'ΔU = (3/2)nRΔT = 1.5 × 3.0 × 8.31 × 50 = 1870 J. Mark scheme (2 marks). C1: ΔU = (3/2)nRΔT. A1: ΔU = 1870 J.', 2, NULL, NULL),
('9ebad5c0-dbfa-5c43-af75-767d8d3e3e90', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 15, 15, 'A ball is thrown so that it moves faster. Does its internal energy change?', NULL, 1, 'multiple_choice'::answer_type, 'No: the kinetic energy of the whole ball is not part of its internal energy', NULL, false, NULL, false, NULL, 'Internal energy counts only random molecular motion relative to the centre of mass, not ordered motion of the whole object. Mark scheme (1 mark). B1: C (No: the kinetic energy of the whole ball is not part of its internal energy).', 1, NULL, NULL),
('6e374da6-6e62-5424-a9bf-2e484acbf82a', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 16, 16, 'Two identical blocks are at the same temperature. Block X is 10 m higher than block Y. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'They have the same internal energy', NULL, false, NULL, false, NULL, 'Gravitational potential energy of the whole block is not internal energy. Same material and temperature means the same internal energy. Mark scheme (1 mark). B1: A (They have the same internal energy).', 1, NULL, NULL),
('8cdc4121-4668-5af0-91fd-9681dad23fef', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 17, 17, 'A monatomic gas has internal energy 4500 J at 300 K. What is its internal energy at 400 K?', NULL, 1, 'numeric'::answer_type, '6000', 'J', false, NULL, false, NULL, 'U ∝ T for an ideal gas: U = 4500 × 400 ÷ 300 = 6000 J. Mark scheme (2 marks). C1: U ∝ T. A1: U = 6000 J.', 2, NULL, NULL),
('c2b452ea-bed9-54b3-a36d-63750d00e4b5', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 18, 18, 'What happens to the internal energy of water as it freezes at 0 °C?', NULL, 1, 'multiple_choice'::answer_type, 'It decreases', NULL, false, NULL, false, NULL, 'Freezing releases energy as bonds form, so the potential energy (and internal energy) decreases at constant temperature. Mark scheme (1 mark). B1: D (It decreases).', 1, NULL, NULL),
('1c2877c9-c6a7-5bcc-a1fd-fb0695cccfe2', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 19, 19, 'Calculate the mean kinetic energy of the molecules in 2.0 mol of argon at 250 K, given that the total internal energy is (3/2)nRT. Give your answer in units of 10⁻²¹ J. Take R = 8.31 J K⁻¹ mol⁻¹ and N_A = 6.02 × 10²³ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '5.176', '10⁻²¹ J', false, NULL, false, NULL, 'U = 1.5 × 2.0 × 8.31 × 250 = 6230 J. Mean Ek = U/N = 6232 ÷ (2.0 × 6.02 × 10²³) = 5.18 × 10⁻²¹ J. Mark scheme (2 marks). C1: divide by number of molecules. A1: Ek = 5.18 × 10⁻²¹ J.', 2, NULL, NULL),
('d0dbe217-a5bc-5487-b3e0-e5db1bc52bf0', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 20, 20, 'Which statement about internal energy is correct?', NULL, 1, 'multiple_choice'::answer_type, 'It depends only on the state of the system, not on how it got there', NULL, false, NULL, false, NULL, 'Internal energy is a state function: two routes to the same state give the same U. Mark scheme (1 mark). B1: B (It depends only on the state of the system, not on how it got there).', 1, NULL, NULL),
('530757e1-5048-5743-a299-a9b09c99e452', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 21, 21, 'The internal energy of a gas increases by 900 J when 1200 J is supplied by heating. How much work was done by the gas?', NULL, 1, 'numeric'::answer_type, '300', 'J', false, NULL, false, NULL, 'w = ΔU − q = 900 − 1200 = −300 J. Work done by the gas = q − ΔU = 1200 − 900 = 300 J. Mark scheme (2 marks). C1: ΔU = q + w. A1: W = 300 J.', 2, NULL, NULL),
('c75c8de7-1f80-54c7-8828-4ab9dbeb8644', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 22, 22, 'A copper block is heated from 20 °C to 80 °C. Which energy of its atoms mainly increases?', NULL, 1, 'multiple_choice'::answer_type, 'The random kinetic energy of the vibrating atoms (and their potential energy)', NULL, false, NULL, false, NULL, 'Heating a solid makes its atoms vibrate more vigorously: both their random kinetic and potential energies rise. Mark scheme (1 mark). B1: C (The random kinetic energy of the vibrating atoms (and their potential energy)).', 1, NULL, NULL),
('9f01d59f-2c09-5e42-92b5-30550e59dc8d', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 23, 23, 'An ideal monatomic gas at 200 K has internal energy 2.5 kJ. At what temperature is its internal energy 5.0 kJ?', NULL, 1, 'numeric'::answer_type, '400', 'K', false, NULL, false, NULL, 'U ∝ T: T = 200 × 5.0 ÷ 2.5 = 400 K. Mark scheme (2 marks). C1: U ∝ T. A1: T = 400 K.', 2, NULL, NULL),
('0b40abb1-99ca-5c98-a567-04e6520b97dc', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 24, 24, 'Why does compressing a gas quickly raise its temperature?', NULL, 1, 'multiple_choice'::answer_type, 'Work done on the gas increases its internal energy, and so the molecules'' mean kinetic energy', NULL, false, NULL, false, NULL, 'w > 0 with q ≈ 0 gives ΔU > 0; for an ideal gas this means a higher temperature. Mark scheme (1 mark). B1: A (Work done on the gas increases its internal energy, and so the molecules'' mean kinetic energy).', 1, NULL, NULL),
('368a5c75-fa43-5315-b1ff-29573921b9dc', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 25, 25, 'A sample of 0.50 mol of neon (monatomic) at 300 K is heated at constant volume until its internal energy rises by 1500 J. Calculate its final temperature. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '540.7', 'K', false, NULL, false, NULL, 'ΔT = ΔU/((3/2)nR) = 1500 ÷ (1.5 × 0.50 × 8.31) = 241 K. Final T = 300 + 240.7 = 541 K. Mark scheme (3 marks). C1: ΔU = (3/2)nRΔT. C1: ΔT. C1: add.', 3, NULL, NULL),
('4db86114-9db2-55d5-beb0-87a67abba89f', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 26, 26, 'A liquid is heated at its boiling point. Which row is correct for the molecules?', NULL, 2, 'multiple_choice'::answer_type, 'Mean kinetic energy unchanged; potential energy increases', NULL, false, NULL, false, NULL, 'At constant temperature the mean Ek is unchanged; energy goes into separating the molecules (Ep rises). Mark scheme (3 marks). C1: constant T. C1: potential energy rises. A1: D (Mean kinetic energy unchanged; potential energy increases).', 3, NULL, NULL),
('93430775-ab0a-553d-ac03-461022a77344', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 27, 27, 'A gas absorbs 800 J by heating and its internal energy rises by 500 J. Calculate the work done on the gas and state what this means physically. Give the work done on the gas.', NULL, 2, 'numeric'::answer_type, '-300', 'J', false, NULL, true, NULL, 'w = ΔU − q = 500 − 800 = −300 J: the gas did 300 J of work on its surroundings (it expanded). Mark scheme (3 marks). C1: w = ΔU − q. B1: interpretation. A1: w = −300 J.', 3, NULL, NULL),
('ee08b25b-fe18-566a-9054-752b4c5b4a94', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 28, 28, 'Two moles of a monatomic ideal gas are heated from 0 °C to 100 °C. Calculate the increase in internal energy, and the mean increase in kinetic energy per molecule. Give the increase per molecule in units of 10⁻²¹ J. Take R = 8.31 J K⁻¹ mol⁻¹ and N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '2.071', '10⁻²¹ J', false, NULL, false, NULL, 'ΔU = 1.5nRΔT = 1.5 × 2 × 8.31 × 100 = 2490 J. Per molecule: 2493 ÷ (2 × 6.02 × 10²³) = 2.07 × 10⁻²¹ J. Mark scheme (4 marks). C1: ΔT = 100 K. C1: ΔU. C1: ÷ number of molecules. A1: Δ⟨Ek⟩ = 2.07 × 10⁻²¹ J.', 4, NULL, NULL),
('14bfeba1-d3be-5f8c-a3bf-d536baeff194', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 29, 29, 'Why does the internal energy of a real gas depend on its volume as well as its temperature, but that of an ideal gas does not?', NULL, 2, 'multiple_choice'::answer_type, 'Real gas molecules attract each other, so their potential energy depends on their separation', NULL, false, NULL, false, NULL, 'Intermolecular forces give real molecules potential energy that varies with spacing; ideal gas molecules have none. Mark scheme (3 marks). C1: intermolecular forces. C1: Ep depends on separation. A1: B (Real gas molecules attract each other, so their potential energy depends on their separation).', 3, NULL, NULL),
('82cc11b1-ab4b-5751-baee-bb554562a6c8', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 30, 30, 'A 0.20 kg lead bullet travelling at 300 m s⁻¹ hits a steel plate and stops. Assuming all its kinetic energy becomes internal energy of the bullet, calculate the increase in internal energy.', NULL, 2, 'numeric'::answer_type, '9000', 'J', false, NULL, false, NULL, 'ΔU = ½mv² = 0.5 × 0.20 × 300² = 9000 J. Mark scheme (3 marks). C1: Ek = ½mv². B1: becomes internal energy. A1: ΔU = 9000 J.', 3, NULL, NULL),
('5a0908b4-17ba-55a3-9819-867c2a09fff9', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 31, 31, 'In the previous situation, lead has c = 130 J kg⁻¹ K⁻¹. If 60 % of the bullet''s kinetic energy (9000 J) heats the bullet, calculate its temperature rise.', NULL, 2, 'numeric'::answer_type, '207.7', 'K', false, NULL, false, NULL, 'Energy to bullet = 0.60 × 9000 = 5400 J. ΔT = E/(mc) = 5400 ÷ (0.20 × 130) = 208 K. Mark scheme (4 marks). C1: 60 % of Ek. C1: mcΔθ. C1: rearranged. A1: ΔT = 208 K.', 4, NULL, NULL),
('23746abd-a2e9-53b4-a48f-952dbc16cd29', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 32, 32, 'Which process leaves the internal energy of an ideal gas unchanged?', NULL, 2, 'multiple_choice'::answer_type, 'An isothermal expansion', NULL, false, NULL, false, NULL, 'U depends only on T for an ideal gas; isothermal means constant T. Mark scheme (3 marks). C1: U depends only on T. C1: isothermal. A1: C (An isothermal expansion).', 3, NULL, NULL),
('a95e791a-5767-5a1c-ab66-7daa5a50b9aa', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 33, 33, 'Water falls 50 m over a waterfall. Assuming all the gravitational potential energy becomes internal energy of the water, calculate the rise in temperature. Take g = 9.81 m s⁻². Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.', NULL, 2, 'numeric'::answer_type, '0.1168', 'K', false, NULL, false, NULL, 'mgh = mcΔθ, so Δθ = gh/c = 9.81 × 50 ÷ 4200 = 0.117 K. Mark scheme (3 marks). C1: mgh = mcΔθ. C1: mass cancels. A1: Δθ = 0.117 K.', 3, NULL, NULL),
('9ef98519-ce4c-5c60-83dd-a6eb748b0cda', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 34, 34, 'A gas is taken from state X to state Y by two routes. Route 1: q = 600 J, w = −200 J. Route 2: q = 450 J. What is w for route 2?', NULL, 2, 'multiple_choice'::answer_type, '−50 J', NULL, false, NULL, false, NULL, 'ΔU is the same for both: route 1 gives ΔU = 400 J. Route 2: w = ΔU − q = 400 − 450 = −50 J. Mark scheme (4 marks). C1: ΔU same for both routes. C1: ΔU = 400 J. C1: w = −50 J. A1: A (−50 J).', 4, NULL, NULL),
('aee89768-bfe8-5a07-b5d4-cfc491b5c0b7', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 35, 35, 'A monatomic gas sample has internal energy 3.0 kJ. It does 1.2 kJ of work while 0.8 kJ is supplied by heating. Calculate its new internal energy.', NULL, 2, 'numeric'::answer_type, '2600', 'J', false, NULL, false, NULL, 'ΔU = q + w = 800 − 1200 = −400 J. New U = 3000 − 400 = 2600 J. Mark scheme (3 marks). C1: ΔU = q + w. C1: add to original. A1: U = 2600 J.', 3, NULL, NULL),
('fb9f7c0b-43d0-52e7-bfd5-4d74a82f6ec1', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 36, 36, 'A hot metal block at 200 °C is dropped into cold water and both reach 30 °C. Which statement about energy is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The internal energy lost by the block equals the internal energy gained by the water (if none is lost)', NULL, false, NULL, false, NULL, 'Energy is conserved: heat flows from block to water until they are at the same temperature. Mark scheme (3 marks). C1: energy conserved. C1: transfer until equal temperature. A1: D (The internal energy lost by the block equals the internal energy gained by the water (if none is lost)).', 3, NULL, NULL),
('22711509-4ed8-511a-9aa9-acc28ac66004', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 37, 37, 'A car of mass 1200 kg brakes from 25 m s⁻¹ to rest. The brake discs (total mass 12 kg, c = 450 J kg⁻¹ K⁻¹) absorb 80 % of the kinetic energy. Calculate the rise in temperature of the discs.', NULL, 2, 'numeric'::answer_type, '55.56', 'K', false, NULL, false, NULL, 'Ek = ½ × 1200 × 25² = 3.75 × 10⁵ J. To discs: 0.80 × 3.750 × 10⁵ = 3.000 × 10⁵ J. ΔT = 300000 ÷ (12 × 450) = 55.6 K. Mark scheme (4 marks). C1: Ek. C1: 80 %. C1: ΔT = E/mc. A1: ΔT = 55.6 K.', 4, NULL, NULL),
('4aae3865-5c21-5e89-a3f1-8ca2db0ca65f', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 38, 38, 'At what temperature would a monatomic ideal gas of 0.10 mol have internal energy 500 J? Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '401.1', 'K', false, NULL, false, NULL, 'T = U/((3/2)nR) = 500 ÷ (1.5 × 0.10 × 8.31) = 401 K. Mark scheme (3 marks). C1: U = (3/2)nRT. C1: rearranged. A1: T = 401 K.', 3, NULL, NULL),
('a0d4026e-d345-501a-99f9-170f64989585', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 39, 39, 'A sealed bag of air is carried up a mountain at constant temperature and its volume increases. Assuming ideal behaviour, what happens to its internal energy?', NULL, 2, 'multiple_choice'::answer_type, 'It stays the same', NULL, false, NULL, false, NULL, 'Ideal gas: U depends only on T. Constant T means constant U. Mark scheme (3 marks). C1: U = f(T) only. C1: T constant. A1: B (It stays the same).', 3, NULL, NULL),
('26370223-2e68-5e0e-b425-25845664dd7d', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 40, 40, 'A 2.0 kg aluminium block (c = 900 J kg⁻¹ K⁻¹) at 20 °C is hammered 100 times; each blow does 15 J of work on it. Half of the energy goes into the block. Calculate its temperature rise.', NULL, 2, 'numeric'::answer_type, '0.4167', 'K', false, NULL, false, NULL, 'Energy to block = 0.5 × 100 × 15 = 750 J. ΔT = 750 ÷ (2.0 × 900) = 0.417 K. Mark scheme (4 marks). C1: total work. C1: half to block. C1: ΔT = E/mc. A1: ΔT = 0.417 K.', 4, NULL, NULL),
('0e672aad-a9ca-5379-a0a3-9de815e83cea', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 41, 41, 'A sample of 0.60 mol of argon (monatomic) loses 450 J of internal energy. Calculate its fall in temperature. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '60.17', 'K', false, NULL, false, NULL, 'ΔT = ΔU/((3/2)nR) = 450 ÷ (1.5 × 0.60 × 8.31) = 60.2 K. Mark scheme (3 marks). C1: ΔU = (3/2)nRΔT. C1: rearranged. A1: ΔT = 60.2 K.', 3, NULL, NULL),
('b1820cdf-5d6c-5682-9329-c8ce9bd1c645', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 42, 42, 'A cylinder of 0.040 mol of helium (monatomic) at 300 K and 1.0 × 10⁵ Pa is heated at constant pressure to 450 K. (a) Calculate the increase in internal energy. (b) Calculate the work done by the gas, using pΔV = nRΔT. (c) Calculate the heat supplied. Give only the answer to (c). Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '124.7', 'J', false, NULL, false, NULL, '(a) ΔU = 1.5nRΔT = 1.5 × 0.040 × 8.31 × 150 = 74.8 J. (b) W = nRΔT = 0.040 × 8.31 × 150 = 49.9 J. (c) q = ΔU + W = 74.79 + 49.86 = 125 J. Mark scheme (6 marks). C1: ΔU = 1.5nRΔT. A1: ΔU. C1: W = nRΔT. A1: W. C1: q = ΔU − w. A1: q = 125 J.', 6, NULL, NULL),
('912e399c-1ed7-5dc5-8fef-ad4a89fa13da', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 43, 43, 'A lead shot of mass 0.50 kg falls 1.2 m inside a closed tube; the tube is inverted 50 times so the shot falls 50 times. Lead has c = 130 J kg⁻¹ K⁻¹. (a) Calculate the total loss of gravitational potential energy. (b) State where it goes. (c) Calculate the temperature rise of the lead, assuming no losses. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '4.528', 'K', false, NULL, false, NULL, '(a) 50 × 0.50 × 9.81 × 1.2 = 294 J. (b) Into internal energy of the lead (and a little to the tube and air). (c) ΔT = E/(mc) = 294.3 ÷ (0.50 × 130) = 4.53 K. Mark scheme (5 marks). C1: 50mgh. A1: Ep. B1: internal energy. C1: ΔT = E/mc. A1: ΔT = 4.53 K.', 5, NULL, NULL),
('dd0d21aa-ccb9-504d-9b9b-b334d66417c7', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 44, 44, 'When 1.0 kg of water boils at 100 °C and atmospheric pressure (1.01 × 10⁵ Pa) its volume increases from 1.0 × 10⁻³ m³ to 1.67 m³. L_v = 2.26 × 10⁶ J kg⁻¹. (a) Calculate the work done pushing back the atmosphere. (b) Calculate the increase in internal energy. (c) Calculate the percentage of the latent heat that increases the internal energy. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '92.54', '%', false, NULL, false, NULL, '(a) W = pΔV = 1.01 × 10⁵ × (1.67 − 0.001) = 1.69 × 10⁵ J. (b) ΔU = q − W = 2.26 × 10⁶ − 1.686 × 10⁵ = 2.09 × 10⁶ J. (c) 2.091 × 10⁶ ÷ 2.26 × 10⁶ × 100 = 92.5 %. Mark scheme (6 marks). C1: W = pΔV. A1: W. C1: ΔU = q + w with w negative. A1: ΔU. A1: percentage = 92.5%. B1: most energy separates molecules.', 6, NULL, NULL),
('7d716f22-fced-5723-8532-5440d22bcbbc', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 45, 45, 'A monatomic ideal gas (n = 0.25 mol) is compressed adiabatically and its temperature rises from 290 K to 410 K. (a) Calculate ΔU. (b) Calculate the work done on the gas. (c) Explain why the temperature rise would be smaller if the compression were slow. Give only the answer to (b). Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '373.9', 'J', false, NULL, false, NULL, '(a) ΔU = 1.5nRΔT = 1.5 × 0.25 × 8.31 × 120 = 374 J. (b) q = 0, so w = ΔU = 374 J. (c) A slow compression gives time for heat to flow out to the surroundings (q < 0), so ΔU and ΔT are smaller. Mark scheme (5 marks). C1: ΔU formula. A1: ΔU. B1: q = 0. A1: w = 374 J. B1: heat escapes.', 5, NULL, NULL),
('0138970b-5427-5361-bb70-6ecdab9a0aac', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 46, 46, 'A meteorite of mass 2.0 kg enters the atmosphere at 15 km s⁻¹ and is slowed to 200 m s⁻¹. (a) Calculate its loss of kinetic energy. (b) Suggest where the energy goes. (c) If 1 % of it raised the meteorite''s temperature (c = 700 J kg⁻¹ K⁻¹), calculate the temperature rise, and comment. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1607', 'K', false, NULL, false, NULL, '(a) ΔEk = ½ × 2.0 × (15000² − 200²) = 2.25 × 10⁸ J. (b) Internal energy of the air and meteorite, light and sound. (c) ΔT = 0.01 × 2.250 × 10⁸ ÷ (2.0 × 700) = 1610 K — far above melting, so the surface vaporises (ablates). Mark scheme (5 marks). C1: ΔEk. A1: ΔEk. B1: internal energy of air/meteorite. C1: ΔT = E/mc. A1: ΔT = 1610 K.', 5, NULL, NULL),
('88ffad9b-0dfe-5490-a6eb-0f3f8056e6f8', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 47, 47, 'An ideal monatomic gas (n = 0.10 mol) is taken from 300 K to 500 K by two routes. Route P: constant volume then nothing else. Route Q: constant pressure. (a) Calculate ΔU for each route. (b) For route Q, calculate the work done by the gas (pΔV = nRΔT). (c) Calculate the heat supplied in each route. Give only the heat for route Q in (c). Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 3, 'numeric'::answer_type, '415.5', 'J', false, NULL, false, NULL, '(a) ΔU = 1.5nRΔT = 1.5 × 0.10 × 8.31 × 200 = 249 J for both (state function). (b) W = nRΔT = 0.10 × 8.31 × 200 = 166 J. (c) P: q = ΔU = 249 J. Q: q = ΔU + W = 249.3 + 166.2 = 416 J. Mark scheme (6 marks). A1: ΔU same for both. B1: state function. A1: W. A1: q for P. C1: q = ΔU + W. A1: q = 416 J.', 6, NULL, NULL),
('ec91eae3-3ee3-55d9-a31b-c8a61f79b87e', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 48, 48, 'A copper rod (mass 0.40 kg, c = 385 J kg⁻¹ K⁻¹) is rubbed with a cloth. The cloth is pushed back and forth through 0.20 m against a friction force of 30 N, 200 times. (a) Calculate the work done against friction. (b) Half of this energy enters the rod. Calculate its temperature rise. (c) Explain why the rod''s internal energy increases even though no heating by a hotter object occurs. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '3.896', 'K', false, NULL, false, NULL, '(a) W = 200 × 30 × 0.20 = 1200 J. (b) ΔT = 0.5 × 1200 ÷ (0.40 × 385) = 3.90 K. (c) Work done (not heat) transfers energy to the random motion of the rod''s atoms: internal energy can rise by work as well as by heating. Mark scheme (5 marks). C1: W = Fd × number. A1: W. C1: ΔT = E/mc. A1: ΔT = 3.90 K. B1: work raises internal energy.', 5, NULL, NULL),
('b6194454-981a-514b-948e-bf286f0f2f8f', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 49, 49, 'The internal energy of a real gas is U = (3/2)nRT − a(n²/V) for a constant a = 0.14 J m³ mol⁻². 1.0 mol of the gas expands at constant temperature (300 K) from 1.0 × 10⁻³ m³ to 2.0 × 10⁻³ m³. (a) Explain why the second term is negative. (b) Calculate ΔU. (c) Explain why ΔU would be zero for an ideal gas. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '70', 'J', false, NULL, false, NULL, '(a) The molecules attract, so their potential energy is negative, and more negative when they are closer (smaller V). (b) ΔU = a n²(1/V₁ − 1/V₂) = 0.14 × (1 ÷ 1.0 × 10⁻³ − 1 ÷ 2.0 × 10⁻³) = 70.0 J. (c) An ideal gas has no intermolecular forces, so U depends only on T. Mark scheme (6 marks). B1: attraction gives negative Ep. B1: more negative when closer. C1: ΔU from the a term. A1: ΔU = 70 J. B1: ideal gas U = f(T). B1: no Ep.', 6, NULL, NULL),
('a6885b9d-6722-56b5-acb1-525bf9ab9e73', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57651263-6bbc-5909-9535-85c599a55166', 'a-level', '19.3', '9702 coursebook 19.3 · Internal energy', 50, 50, 'A cylinder holds 0.20 mol of helium at 300 K. 250 J of heat is supplied and the gas does 100 J of work. (a) Calculate ΔU. (b) Calculate the final temperature using ΔU = (3/2)nRΔT. (c) Calculate the mean kinetic energy per atom at the final temperature using (3/2)kT. Give only the answer to (b). Take R = 8.31 J K⁻¹ mol⁻¹ and k = 1.38 × 10⁻²³ J K⁻¹.', NULL, 3, 'numeric'::answer_type, '360.2', 'K', false, NULL, false, NULL, '(a) ΔU = 250 − 100 = 150 J. (b) ΔT = 150 ÷ (1.5 × 0.20 × 8.31) = 60.2 K, T = 300 + 60.17 = 360 K. (c) ⟨Ek⟩ = 1.5 × 1.38 × 10⁻²³ × 360.2 = 7.46 × 10⁻²¹ J. Mark scheme (5 marks). A1: ΔU. C1: ΔT. A1: T. C1: (3/2)kT. A1: T = 360 K.', 5, NULL, NULL)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('fda9c168-9a2f-5e94-b8db-22c49869c2e2', 'ba469cd4-7094-58ba-8542-014591f56b9d', 'The kinetic energy of the substance as a whole', 'A', false, 0),
('ac549ea8-233b-5ef3-b5ac-c8a40309e02f', 'ba469cd4-7094-58ba-8542-014591f56b9d', 'The heat it contains', 'B', false, 1),
('140d5a8a-ddfe-5df9-ae8a-01958ac6e422', 'ba469cd4-7094-58ba-8542-014591f56b9d', 'The sum of the random kinetic and potential energies of all its molecules', 'C', true, 2),
('1fce72b6-5568-59ba-8809-62122b0718f0', 'ba469cd4-7094-58ba-8542-014591f56b9d', 'The potential energy due to its height', 'D', false, 3),
('c1616039-97b6-50d1-ac94-70852d6c986f', '946751f9-5cc4-5a42-8fd7-729759f08bf4', 'There are no forces between the molecules, so they have no potential energy', 'A', true, 0),
('a611c7b7-5bcb-5a41-8973-245d02754ca8', '946751f9-5cc4-5a42-8fd7-729759f08bf4', 'The molecules do not move', 'B', false, 1),
('87f82441-b00e-5093-8684-86a71da25643', '946751f9-5cc4-5a42-8fd7-729759f08bf4', 'The molecules are very heavy', 'C', false, 2),
('9a192c12-de46-5124-b4b7-b3e735e8d373', '946751f9-5cc4-5a42-8fd7-729759f08bf4', 'The gas is always hot', 'D', false, 3),
('c92aee34-cafc-5bc2-b0d1-27a420ea8d8e', 'e65b1296-7591-533c-9289-1356d7efaff7', 'It stays the same, because the temperature is constant', 'A', false, 0),
('411c868f-c662-522b-85b9-0bbfc39499bb', 'e65b1296-7591-533c-9289-1356d7efaff7', 'It decreases', 'B', false, 1),
('14e8ed46-db37-5579-8541-c296f5a43afb', 'e65b1296-7591-533c-9289-1356d7efaff7', 'It increases because the kinetic energy increases', 'C', false, 2),
('9476cc59-018f-5f9f-8199-1303c427af1b', 'e65b1296-7591-533c-9289-1356d7efaff7', 'It increases, because the molecular potential energy increases', 'D', true, 3),
('2e413837-f163-5ba3-91ee-adb46833d5b9', '7452a050-6ec0-527f-9e14-801827203536', 'Letting it expand adiabatically', 'A', false, 0),
('13ce80ca-751f-56f1-9dd6-e0d84a8de45f', '7452a050-6ec0-527f-9e14-801827203536', 'Heating it at constant volume', 'B', true, 1),
('a0430837-ed50-5dba-b0c2-5a3592355eb2', '7452a050-6ec0-527f-9e14-801827203536', 'Cooling it', 'C', false, 2),
('2c925d7b-2d31-5f63-a9dc-de2272191103', '7452a050-6ec0-527f-9e14-801827203536', 'Letting it do work with no heat supplied', 'D', false, 3),
('d505ea9a-c630-521d-9e31-57a862d1efcd', '9ebad5c0-dbfa-5c43-af75-767d8d3e3e90', 'Yes, it increases', 'A', false, 0),
('e874f41b-0500-5b90-aa34-bf9b91006830', '9ebad5c0-dbfa-5c43-af75-767d8d3e3e90', 'Yes, it decreases', 'B', false, 1),
('14463482-6733-5656-a988-73319e8c5e2b', '9ebad5c0-dbfa-5c43-af75-767d8d3e3e90', 'No: the kinetic energy of the whole ball is not part of its internal energy', 'C', true, 2),
('e0b417d0-e0e7-5cf8-80c9-a9e506efe9db', '9ebad5c0-dbfa-5c43-af75-767d8d3e3e90', 'Only if it spins', 'D', false, 3),
('5186a4c6-14d0-51ac-a848-b57a43e18489', '6e374da6-6e62-5424-a9bf-2e484acbf82a', 'They have the same internal energy', 'A', true, 0),
('e64da28a-045b-5d45-999d-251be76dddd4', '6e374da6-6e62-5424-a9bf-2e484acbf82a', 'X has more internal energy', 'B', false, 1),
('2bf7c1c3-9381-5929-800d-1c233b0dc09c', '6e374da6-6e62-5424-a9bf-2e484acbf82a', 'Y has more internal energy', 'C', false, 2),
('841729b9-b48e-599b-9d50-dce1c4387429', '6e374da6-6e62-5424-a9bf-2e484acbf82a', 'X has less internal energy', 'D', false, 3),
('47c52c9f-1293-586b-b1fd-70d0ffc94377', 'c2b452ea-bed9-54b3-a36d-63750d00e4b5', 'It increases', 'A', false, 0),
('d833bcea-66c9-5082-a312-e27ff4041372', 'c2b452ea-bed9-54b3-a36d-63750d00e4b5', 'It stays the same', 'B', false, 1),
('74578a18-1de4-5831-9da8-c896caeffd0a', 'c2b452ea-bed9-54b3-a36d-63750d00e4b5', 'It becomes zero', 'C', false, 2),
('3b490193-6128-5072-a5f2-99b1387a89e6', 'c2b452ea-bed9-54b3-a36d-63750d00e4b5', 'It decreases', 'D', true, 3),
('df034e34-cbf4-5dbe-a1f7-d34dd65a2b92', 'd0dbe217-a5bc-5487-b3e0-e5db1bc52bf0', 'It depends on the route taken to reach the state', 'A', false, 0),
('9c1ca9de-6e62-5758-9e40-43e7d780141a', 'd0dbe217-a5bc-5487-b3e0-e5db1bc52bf0', 'It depends only on the state of the system, not on how it got there', 'B', true, 1),
('f3c8b683-3d1e-58ab-8aa1-4a210c81a8ff', 'd0dbe217-a5bc-5487-b3e0-e5db1bc52bf0', 'It is the same as temperature', 'C', false, 2),
('ac8072e9-9328-5a2a-98e5-ffc01c280a7a', 'd0dbe217-a5bc-5487-b3e0-e5db1bc52bf0', 'It is always zero for a solid', 'D', false, 3),
('0cbdf31e-e490-5a2f-afe6-bb7fdc81b992', 'c75c8de7-1f80-54c7-8828-4ab9dbeb8644', 'The kinetic energy of the block as a whole', 'A', false, 0),
('cfbcc4b9-b976-53f3-bb13-d52e3ac0db55', 'c75c8de7-1f80-54c7-8828-4ab9dbeb8644', 'The nuclear energy', 'B', false, 1),
('36179a72-ebd3-50fa-a07b-aa1c829b8072', 'c75c8de7-1f80-54c7-8828-4ab9dbeb8644', 'The random kinetic energy of the vibrating atoms (and their potential energy)', 'C', true, 2),
('0b756d2f-db92-500d-bcd1-f188b46b29da', 'c75c8de7-1f80-54c7-8828-4ab9dbeb8644', 'The gravitational potential energy', 'D', false, 3),
('0e6feb5f-65d8-5fab-b3e3-3c1e99041ba8', '0b40abb1-99ca-5c98-a567-04e6520b97dc', 'Work done on the gas increases its internal energy, and so the molecules'' mean kinetic energy', 'A', true, 0),
('f7a49528-23bf-5926-980a-fe3e984fdc55', '0b40abb1-99ca-5c98-a567-04e6520b97dc', 'The molecules become heavier', 'B', false, 1),
('e54f06b2-65db-5006-ab7e-6c3da058f4b6', '0b40abb1-99ca-5c98-a567-04e6520b97dc', 'The gas absorbs heat from the pump', 'C', false, 2),
('d0d1c39d-f39c-51d3-897a-037b1f087035', '0b40abb1-99ca-5c98-a567-04e6520b97dc', 'The number of molecules increases', 'D', false, 3),
('20f4f02a-c15c-5900-b826-cfd990276512', '4db86114-9db2-55d5-beb0-87a67abba89f', 'Mean kinetic energy increases; potential energy unchanged', 'A', false, 0),
