('2a83c2d0-94f4-573b-a426-fb83b8e7f925', '4db86114-9db2-55d5-beb0-87a67abba89f', 'Mean kinetic energy unchanged; potential energy increases', 'D', true, 3),
('04d53c15-829b-57dc-a9a2-850c64830c31', '14bfeba1-d3be-5f8c-a3bf-d536baeff194', 'Ideal gases have heavier molecules', 'A', false, 0),
('7084659a-23d7-50eb-98b5-e6d9fc195b54', '14bfeba1-d3be-5f8c-a3bf-d536baeff194', 'Real gas molecules attract each other, so their potential energy depends on their separation', 'B', true, 1),
('48bc3de6-b447-598e-8c22-038bb05b2e1d', '14bfeba1-d3be-5f8c-a3bf-d536baeff194', 'Real gases have no kinetic energy', 'C', false, 2),
