('45232635-ebf8-52d0-a428-edc40aef2f7f', '23746abd-a2e9-53b4-a48f-952dbc16cd29', 'An adiabatic expansion', 'A', false, 0),
('438f71a2-802b-5e16-b6d4-fa9c40f79699', '23746abd-a2e9-53b4-a48f-952dbc16cd29', 'Heating at constant volume', 'B', false, 1),
('d2c9a7c9-a9ab-5226-8b09-e13d4631f44b', '23746abd-a2e9-53b4-a48f-952dbc16cd29', 'An isothermal expansion', 'C', true, 2),
