('7b302b21-8449-5ff8-804f-e1bcbb76cb40', '9ef98519-ce4c-5c60-83dd-a6eb748b0cda', '−200 J', 'B', false, 1),
('7d04b22c-6d30-526a-9216-fc0b4e6d1d62', '9ef98519-ce4c-5c60-83dd-a6eb748b0cda', '+50 J', 'C', false, 2),
('ff1e7f16-654f-525e-b5ba-5685ac404edc', '9ef98519-ce4c-5c60-83dd-a6eb748b0cda', '−650 J', 'D', false, 3),
('4a583212-2d4b-5d16-abeb-859aa94bc680', 'fb9f7c0b-43d0-52e7-bfd5-4d74a82f6ec1', 'The block loses temperature and the water gains temperature in equal amounts', 'A', false, 0),
('884bc496-fb3f-5d6a-bcac-d8db950f7b80', 'fb9f7c0b-43d0-52e7-bfd5-4d74a82f6ec1', 'The block''s internal energy stays the same', 'B', false, 1),
('df2837d6-c3af-57b4-8ceb-65999ceb08a5', 'fb9f7c0b-43d0-52e7-bfd5-4d74a82f6ec1', 'Energy is destroyed as the block cools', 'C', false, 2),
('a7eb663c-d110-5698-b7c3-650aa96227f7', 'fb9f7c0b-43d0-52e7-bfd5-4d74a82f6ec1', 'The internal energy lost by the block equals the internal energy gained by the water (if none is lost)', 'D', true, 3),
('6a25b886-aa3c-524d-910e-935e7a33a24b', 'a0d4026e-d345-501a-99f9-170f64989585', 'It increases because the volume increases', 'A', false, 0),
('7e54f77c-e520-5658-bf2f-e216185899ef', 'a0d4026e-d345-501a-99f9-170f64989585', 'It stays the same', 'B', true, 1),
('f90f5a8e-902c-5f7c-9fd6-cb71408359f2', 'a0d4026e-d345-501a-99f9-170f64989585', 'It decreases because the pressure decreases', 'C', false, 2),
('d40d2fe7-e851-554b-b7dc-07864b074cfd', 'a0d4026e-d345-501a-99f9-170f64989585', 'It becomes zero', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('a9b6c2e4-4543-5a1c-ba98-f59fd94872f0', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 9, 9, 'Two objects are in thermal contact and there is no net flow of energy between them. What can you conclude?', NULL, 1, 'multiple_choice'::answer_type, 'They are at the same temperature', NULL, false, NULL, false, NULL, 'Thermal equilibrium means equal temperatures, not equal internal energies. Mark scheme (1 mark). B1: C (They are at the same temperature).', 1, NULL, NULL),
('074afd7e-0ba2-578c-8796-ae33e3b587b6', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 10, 10, 'In which direction does energy flow by heating between two bodies in contact?', NULL, 1, 'multiple_choice'::answer_type, 'From the hotter body to the colder body', NULL, false, NULL, false, NULL, 'Net heat flow is always from higher to lower temperature, whatever the internal energies. Mark scheme (1 mark). B1: A (From the hotter body to the colder body).', 1, NULL, NULL),
('989b8999-f0f1-5d67-9134-f768a70017dd', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 11, 11, 'A thermometer placed in a cup of tea reads a steady value after a minute. Why?', NULL, 1, 'multiple_choice'::answer_type, 'It has reached thermal equilibrium with the tea', NULL, false, NULL, false, NULL, 'The thermometer reads its own temperature, which equals the tea''s only once they are in thermal equilibrium. Mark scheme (1 mark). B1: D (It has reached thermal equilibrium with the tea).', 1, NULL, NULL),
('82b13afb-0ec4-596a-b2af-d928740e465e', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 12, 12, 'A cup of coffee at 352 K is placed in a room at 293 K. Calculate the temperature difference.', NULL, 1, 'numeric'::answer_type, '59', 'K', false, NULL, false, NULL, 'ΔT = 352 − 293 = 59 K. Mark scheme (1 mark). A1: ΔT = 59 K.', 1, NULL, NULL),
('70c501cb-6083-5359-b4e9-c2818f1010d2', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 13, 13, 'A large iceberg at −2 °C and a hot cup of tea at 90 °C. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'The iceberg can have more internal energy but the tea is at the higher temperature', NULL, false, NULL, false, NULL, 'Internal energy depends on mass and material too; temperature decides the direction of heat flow. Mark scheme (1 mark). B1: B (The iceberg can have more internal energy but the tea is at the higher temperature).', 1, NULL, NULL),
('4e121c19-3859-5a47-a0a0-1a73ed3cf33c', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 14, 14, 'Object A is in thermal equilibrium with B, and B with C. Which is correct?', NULL, 1, 'multiple_choice'::answer_type, 'A and C are in thermal equilibrium', NULL, false, NULL, false, NULL, 'This is the zeroth law of thermodynamics: it is why thermometers work. Mark scheme (1 mark). B1: C (A and C are in thermal equilibrium).', 1, NULL, NULL),
('6fbaa069-edb0-5484-a055-ac2a5b49ade9', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 15, 15, 'A 0.50 kg metal block cools from 80 °C to 30 °C in water, giving 11 250 J to the water. Calculate the specific heat capacity of the metal.', NULL, 1, 'numeric'::answer_type, '450', 'J kg⁻¹ K⁻¹', false, NULL, false, NULL, 'c = E/(mΔθ) = 11250 ÷ (0.50 × 50) = 450 J kg⁻¹ K⁻¹. Mark scheme (2 marks). C1: c = E/mΔθ. A1: c = 450 J kg⁻¹ K⁻¹.', 2, NULL, NULL),
('dd5f3638-492d-5889-92bb-5093254afb73', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 16, 16, 'Two blocks, one of copper and one of wood, are in a room overnight. The copper feels colder to touch. Which is correct?', NULL, 1, 'multiple_choice'::answer_type, 'Both are at the same temperature; copper conducts heat from the hand faster', NULL, false, NULL, false, NULL, 'In equilibrium both are at room temperature; copper''s higher conductivity draws heat from the hand faster. Mark scheme (1 mark). B1: A (Both are at the same temperature; copper conducts heat from the hand faster).', 1, NULL, NULL),
('1fd8f4cd-12c9-5676-a78b-b22491f89851', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 17, 17, 'In an insulated container, a hot block loses 2400 J to some cold water. How much energy does the water gain?', NULL, 1, 'multiple_choice'::answer_type, '2400 J', NULL, false, NULL, false, NULL, 'In an isolated system energy is conserved: the energy lost by the block equals the energy gained by the water. Mark scheme (1 mark). B1: D (2400 J).', 1, NULL, NULL),
('0e173df0-6329-56c3-be17-09ca4c912cd7', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 18, 18, 'Which quantity is the same for two objects in thermal equilibrium?', NULL, 1, 'multiple_choice'::answer_type, 'Temperature', NULL, false, NULL, false, NULL, 'Thermal equilibrium means no net heat flow, which happens only at equal temperatures. Mark scheme (1 mark). B1: B (Temperature).', 1, NULL, NULL),
('a0b2b203-5dc4-54e7-8b73-bb94ce7911f3', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 19, 19, '0.20 kg of water at 60 °C is mixed with 0.20 kg of water at 20 °C. Calculate the final temperature, assuming no losses.', NULL, 1, 'numeric'::answer_type, '40', '°C', false, NULL, false, NULL, 'Equal masses of the same substance: θ = (60 + 20) ÷ 2 = 40 °C. Mark scheme (2 marks). C1: mean of temperatures for equal masses. A1: θ = 40 °C.', 2, NULL, NULL),
('dd6c5fe5-db6f-5315-8c96-6ebe7983f272', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 20, 20, 'Why does a cold drink in a warm room gradually warm up and stop at room temperature?', NULL, 1, 'multiple_choice'::answer_type, 'Energy flows into the drink until it reaches thermal equilibrium with the room', NULL, false, NULL, false, NULL, 'Net heat flows into the drink while it is colder; at equal temperatures the flow stops. Mark scheme (1 mark). B1: C (Energy flows into the drink until it reaches thermal equilibrium with the room).', 1, NULL, NULL),
('b7b85e65-e927-549b-b529-bdfcab720a9c', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 21, 21, 'A 0.10 kg copper block (c = 385 J kg⁻¹ K⁻¹) cools from 95 °C to 25 °C. Calculate the energy it gives out.', NULL, 1, 'numeric'::answer_type, '2695', 'J', false, NULL, false, NULL, 'E = mcΔθ = 0.10 × 385 × 70 = 2695 J. Mark scheme (2 marks). C1: E = mcΔθ. A1: E = 2700 J.', 2, NULL, NULL),
('6e18859c-cf94-5c4b-a768-c7a48ea052de', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 22, 22, 'Which is the best definition of temperature (in the kinetic model)?', NULL, 1, 'multiple_choice'::answer_type, 'A measure of the average random kinetic energy of the particles', NULL, false, NULL, false, NULL, 'For an ideal gas the mean translational kinetic energy is (3/2)kT: temperature measures it. Mark scheme (1 mark). B1: A (A measure of the average random kinetic energy of the particles).', 1, NULL, NULL),
('3240ca9e-3da7-5393-b6c4-7a629981c200', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 23, 23, 'A 0.40 kg iron block (c = 450 J kg⁻¹ K⁻¹) at 100 °C is placed in 0.60 kg of water at 18 °C in an insulated container. Calculate the final temperature. Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.', NULL, 2, 'numeric'::answer_type, '23.47', '°C', false, NULL, false, NULL, 'Heat lost by iron = heat gained by water: 0.40 × 450 × (100 − θ) = 0.60 × 4200 × (θ − 18). 18000 − 180θ = 2520θ − 45360, θ = 63360 ÷ 2700 = 23.5 °C. Mark scheme (3 marks). M1: heat lost = heat gained. C1: substitution. C1: solve.', 3, NULL, NULL),
('e146a13c-9e12-5db7-ae25-5c2c93f53d6a', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 24, 24, 'A 0.25 kg aluminium block at 150 °C is dropped into 0.50 kg of water at 20 °C. The final temperature is 32 °C. Calculate the specific heat capacity of aluminium. Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.', NULL, 2, 'numeric'::answer_type, '854.2', 'J kg⁻¹ K⁻¹', false, NULL, false, NULL, 'Heat gained by water = 0.50 × 4200 × 12 = 25200 J. Heat lost by Al = 0.25 × c × 118. c = 25200 ÷ (0.25 × 118) = 854 J kg⁻¹ K⁻¹. Mark scheme (4 marks). C1: heat gained by water. C1: equated to heat lost. C1: rearranged. A1: c = 854 J kg⁻¹ K⁻¹.', 4, NULL, NULL),
('583cdfaa-901c-57b2-83d4-4f2b5cd267ee', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 25, 25, 'In a method-of-mixtures experiment the final temperature is lower than predicted. Which is the most likely reason?', NULL, 2, 'multiple_choice'::answer_type, 'Heat was lost to the container and surroundings', NULL, false, NULL, false, NULL, 'Losses to the surroundings mean less energy stays in the mixture, so it ends cooler. Mark scheme (3 marks). C1: energy lost. C1: lower final temperature. A1: D (Heat was lost to the container and surroundings).', 3, NULL, NULL),
('443dc962-9ce3-58d8-9d72-d2ec62ac4fd6', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 26, 26, 'A 50 g ball bearing (c = 460 J kg⁻¹ K⁻¹) at 300 °C is dropped into 0.20 kg of oil (c = 2000 J kg⁻¹ K⁻¹) at 20 °C. Calculate the final temperature.', NULL, 2, 'numeric'::answer_type, '35.22', '°C', false, NULL, false, NULL, '0.050 × 460 × (300 − θ) = 0.20 × 2000 × (θ − 20). 6900 − 23θ = 400θ − 8000, θ = 14900 ÷ 423 = 35.2 °C. Mark scheme (3 marks). M1: heat balance. C1: substitution. C1: solve.', 3, NULL, NULL),
('a394c93c-ad68-566a-8422-876b2d31f244', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 27, 27, 'Two equal masses, one of water and one of copper, start at 80 °C and cool in the same room. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The copper cools faster, because it has a smaller specific heat capacity', NULL, false, NULL, false, NULL, 'For the same energy loss per second, the smaller heat capacity (mc) gives a faster temperature fall. Both end at room temperature. Mark scheme (3 marks). C1: smaller c. C1: larger temperature change per joule. A1: B (The copper cools faster, because it has a smaller specific heat capacity).', 3, NULL, NULL),
('2ebaac07-4a53-599f-b6b7-f2d66ad160fa', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 28, 28, 'A thermometer of heat capacity 12 J K⁻¹ at 20 °C is placed in 0.030 kg of water at 60 °C. Calculate the temperature it reads, ignoring other losses. Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.', NULL, 2, 'numeric'::answer_type, '56.52', '°C', false, NULL, false, NULL, '12 × (θ − 20) = 0.030 × 4200 × (60 − θ). 12θ − 240 = 7560 − 126θ, θ = 7800 ÷ 138 = 56.5 °C — the thermometer lowers the water temperature it measures. Mark scheme (4 marks). M1: heat balance with heat capacity. C1: substitution. C1: solve. A1: θ = 56.5 °C.', 4, NULL, NULL),
('b111eee2-66c0-5497-96e0-2ad34fa3d9f5', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 29, 29, 'Hot water at 70 °C is added to 2.0 kg of cold water at 15 °C to make a bath at 40 °C. Calculate the mass of hot water needed, ignoring losses.', NULL, 2, 'numeric'::answer_type, '1.667', 'kg', false, NULL, false, NULL, 'm × (70 − 40) = 2.0 × (40 − 15), so m = 2.0 × 25 ÷ 30 = 1.67 kg. Mark scheme (3 marks). C1: heat lost = heat gained. C1: c cancels. C1: solve.', 3, NULL, NULL),
('35ab980a-ad7d-5b91-b857-2e27425a8c74', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 30, 30, 'A hot pan is plunged into a sink of cold water. After a while both are at 35 °C. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The pan and water are in thermal equilibrium; the water''s temperature rise was smaller because its heat capacity is larger', NULL, false, NULL, false, NULL, 'Equal temperatures mean equilibrium; the larger heat capacity of the water meant it warmed only a little. Mark scheme (3 marks). C1: equilibrium. C1: heat capacity explains different changes. A1: C (The pan and water are in thermal equilibrium; the water''s temperature rise was smaller because its heat capacity is larger).', 3, NULL, NULL),
('05161b03-694f-578f-9c6d-2836c5193f61', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 31, 31, 'A 2.0 kW immersion heater is placed in 4.0 kg of water at 15 °C. Half the heater''s energy is lost to the surroundings. Calculate the time to reach 45 °C. Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.', NULL, 2, 'numeric'::answer_type, '504', 's', false, NULL, false, NULL, 'Useful power = 0.5 × 2000 = 1000 W. E = mcΔθ = 4.0 × 4200 × 30 = 504000 J. t = 504000 ÷ 1000 = 504 s. Mark scheme (4 marks). C1: useful power. C1: E = mcΔθ. C1: t = E/P. A1: t = 504 s.', 4, NULL, NULL),
('f01849ff-0c63-5f70-8dbc-1c87bdaf498a', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 32, 32, 'A copper calorimeter is used in a mixtures experiment but its heat capacity is ignored in the calculation. The calorimeter starts at the same temperature as the cold water. What effect does this have on the calculated specific heat capacity of a hot metal sample?', NULL, 2, 'multiple_choice'::answer_type, 'It makes the calculated value too small', NULL, false, NULL, false, NULL, 'The calorimeter also absorbs heat from the sample, which is not counted, so the energy lost by the sample is underestimated: c is too small. Mark scheme (4 marks). C1: calorimeter absorbs heat. C1: energy gained underestimated. C1: c too small. A1: A (It makes the calculated value too small).', 4, NULL, NULL),
('ff208973-12a8-5949-adc8-8dc818d5a400', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 33, 33, 'A 0.30 kg lump of lead (c = 130 J kg⁻¹ K⁻¹) at 90 °C is dropped into 0.10 kg of water at 20 °C. Calculate the final temperature. Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.', NULL, 2, 'numeric'::answer_type, '25.95', '°C', false, NULL, false, NULL, '0.30 × 130 × (90 − θ) = 0.10 × 4200 × (θ − 20). 3510 − 39θ = 420θ − 8400, θ = 11910 ÷ 459 = 25.9 °C. Mark scheme (3 marks). M1: heat balance. C1: substitution. C1: solve.', 3, NULL, NULL),
('28ad33f4-ed3e-5a2a-9524-3155345f05c3', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 34, 34, 'A large bath and a small cup both contain water at 40 °C. They are each placed in a room at 20 °C. Which reaches room temperature first?', NULL, 2, 'multiple_choice'::answer_type, 'The cup, because it has a much smaller heat capacity', NULL, false, NULL, false, NULL, 'Rate of cooling depends on surface area, but the bath''s far larger heat capacity means it takes far longer. Mark scheme (3 marks). C1: heat capacity. C1: cup cools faster. A1: D (The cup, because it has a much smaller heat capacity).', 3, NULL, NULL),
('2494c6be-3cd3-5ea2-94eb-1a0377bf2491', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 35, 35, 'A 0.080 kg brass weight (c = 380 J kg⁻¹ K⁻¹) at 100 °C is put into 0.15 kg of water at 20 °C in a 0.10 kg copper can (c = 390 J kg⁻¹ K⁻¹) also at 20 °C. Calculate the final temperature. Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.', NULL, 2, 'numeric'::answer_type, '23.48', '°C', false, NULL, false, NULL, 'Heat lost by brass = heat gained by water and can: 0.080 × 380 × (100 − θ) = (0.15 × 4200 + 0.10 × 390)(θ − 20). 3040 − 30.4θ = 669θ − 13380, θ = 16420 ÷ 699.4 = 23.5 °C. Mark scheme (4 marks). M1: include the can. C1: substitution. C1: solve. A1: θ = 23.5 °C.', 4, NULL, NULL),
('2b0092b0-6bed-57d8-bfd7-dc403a5d19e9', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 36, 36, 'The temperature of a 1.5 kg concrete block (c = 880 J kg⁻¹ K⁻¹) in a sunny window rises from 18 °C to 31 °C. Calculate the energy it absorbed.', NULL, 2, 'numeric'::answer_type, '17160', 'J', false, NULL, false, NULL, 'E = mcΔθ = 1.5 × 880 × 13 = 17160 J. Mark scheme (3 marks). C1: E = mcΔθ. C1: Δθ = 13 K. A1: E = 1.72 × 10⁴ J.', 3, NULL, NULL),
('8c2bf181-2150-5f3f-a3f2-ad23fb483b81', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 37, 37, 'Why can a thermometer only measure the temperature of an object once thermal equilibrium is reached?', NULL, 2, 'multiple_choice'::answer_type, 'Before then, heat is still flowing and the thermometer is not at the object''s temperature', NULL, false, NULL, false, NULL, 'A thermometer reads its own temperature; it equals the object''s temperature only when there is no net heat flow. Mark scheme (3 marks). C1: thermometer reads its own temperature. C1: equal at equilibrium. A1: B (Before then, heat is still flowing and the thermometer is not at the object''s temperature).', 3, NULL, NULL),
('a9cb2bec-7729-5b14-84d2-b000c9139f6d', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 38, 38, 'A 25 W lamp is immersed in 0.50 kg of water. 80 % of its electrical power heats the water. Calculate the temperature rise in 10 minutes. Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.', NULL, 2, 'numeric'::answer_type, '5.714', 'K', false, NULL, false, NULL, 'E = 0.80 × 25 × 600 = 12000 J. Δθ = E/(mc) = 12000 ÷ (0.50 × 4200) = 5.71 K. Mark scheme (4 marks). C1: useful energy. C1: t in s. C1: Δθ = E/mc. A1: Δθ = 5.71 K.', 4, NULL, NULL),
('8f7c7837-051f-5ee2-823b-aca7c8e7d4b5', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 39, 39, 'A 0.60 kg stone (c = 800 J kg⁻¹ K⁻¹) heated in a campfire is dropped into 2.0 kg of water at 15 °C. The water reaches 27 °C. Estimate the temperature of the campfire, assuming the stone reached it and no heat was lost. Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.', NULL, 2, 'numeric'::answer_type, '237', '°C', false, NULL, false, NULL, 'Heat gained by water = 2.0 × 4200 × 12 = 100800 J. 0.60 × 800 × (θ − 27) = 100800, so θ = 27 + 100800 ÷ 480 = 237 °C. Mark scheme (3 marks). C1: heat gained by water. C1: heat balance. C1: rearranged.', 3, NULL, NULL),
('838b2bfb-a62e-51b6-88f6-f41cff016ed2', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 40, 40, 'A 0.20 kg copper block (c = 385 J kg⁻¹ K⁻¹) is heated in a flame and then dropped into 0.25 kg of water at 16 °C in an insulated cup. The water rises to 38 °C. (a) Calculate the energy gained by the water. (b) Calculate the temperature of the flame, assuming the block reached it. (c) Suggest why this estimate is too low. Give only the answer to (b). Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.', NULL, 3, 'numeric'::answer_type, '338', '°C', false, NULL, false, NULL, '(a) E = 0.25 × 4200 × 22 = 23100 J. (b) 0.20 × 385 × (θ − 38) = 23100, θ = 38 + 23100 ÷ 77 = 338 °C. (c) The block cools a little while being moved, and some heat escapes, so the estimate is low. Mark scheme (5 marks). C1: mcΔθ for water. A1: E. M1: heat balance. A1: θ = 338 °C. B1: cooling in transfer.', 5, NULL, NULL),
('2fb6d9c0-5426-5d0f-8d4d-7f54225b9b1b', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 41, 41, 'In a continuous-flow heater, water flows at 0.015 kg s⁻¹ through a tube over a heater. With 150 W the outlet is 2.4 K hotter than the inlet; with 250 W it is 4.0 K hotter at the same flow rate. (a) Explain why the rate of heat loss is the same in both. (b) Use P = (dm/dt)cΔθ + h to find c. (c) Calculate the heat-loss rate h. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '4167', 'J kg⁻¹ K⁻¹', false, NULL, false, NULL, '(a) The inlet and outlet temperatures, and so the temperature of the apparatus, are almost the same in both runs, so the heat-loss rate is taken to be the same. (b) 250 − 150 = 0.015 × c × (4.0 − 2.4), c = 100 ÷ 0.024 = 4170 J kg⁻¹ K⁻¹. (c) h = 150 − 0.015 × 4167 × 2.4 = 0 W. Mark scheme (6 marks). B1: losses approximately equal. C1: two equations. M1: subtract. A1: c. C1: substitute back. A1: c = 4170 J kg⁻¹ K⁻¹.', 6, NULL, NULL),
('fff4d678-b66f-5c7d-b276-525096cdb5f7', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 42, 42, 'A 60 kg person drinks 0.50 kg of iced water at 2 °C. The body (c = 3500 J kg⁻¹ K⁻¹, temperature 37 °C) warms the water to 37 °C. (a) Calculate the energy needed to warm the water. (b) If none were replaced, calculate the fall in body temperature. (c) State how the body actually responds. Give only the answer to (b). Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.', NULL, 3, 'numeric'::answer_type, '0.35', 'K', false, NULL, false, NULL, '(a) E = 0.50 × 4200 × 35 = 73500 J. (b) Δθ = E/(mc) = 73500 ÷ (60 × 3500) = 0.350 K. (c) Metabolism increases (and blood flow to the skin falls) so the body temperature is kept almost constant. Mark scheme (5 marks). C1: mcΔθ for water. A1: E. C1: Δθ = E/mc for body. A1: Δθ = 0.350 K. B1: response.', 5, NULL, NULL),
('a3dc38f9-4fed-5e99-b848-d215b122db65', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 43, 43, 'Two blocks, A (0.50 kg, c = 900 J kg⁻¹ K⁻¹, at 80 °C) and B (1.5 kg, c = 450 J kg⁻¹ K⁻¹, at 20 °C), are placed in contact in an insulated box. (a) Calculate their heat capacities. (b) Calculate the final temperature. (c) Calculate the energy transferred from A to B. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '16200', 'J', false, NULL, false, NULL, '(a) C_A = 0.50 × 900 = 450 J K⁻¹, C_B = 1.5 × 450 = 675 J K⁻¹. (b) θ = (450 × 80 + 675 × 20) ÷ (450 + 675) = 44.0 °C. (c) E = C_A × (80 − θ) = 450 × (80 − 44.00) = 1.62 × 10⁴ J. Mark scheme (6 marks). A1: heat capacities. M1: weighted average. A1: θ. C1: E = CΔθ. C1: substitution. A1: E = 1.62 × 10⁴ J.', 6, NULL, NULL),
('8bac13c8-8548-51f9-a4f3-d8f81a397707', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 44, 44, 'A car radiator holds 6.0 kg of coolant (c = 3800 J kg⁻¹ K⁻¹). The engine supplies heat to it at 25 kW. (a) Calculate the rate of temperature rise if no heat is lost. (b) At steady state the radiator loses heat at 25 kW. Explain what this means for the coolant temperature. (c) If the fan fails and the loss falls to 15 kW, calculate the rate of temperature rise. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.4386', 'K s⁻¹', false, NULL, false, NULL, '(a) dθ/dt = P/(mc) = 25000 ÷ (6.0 × 3800) = 1.10 K s⁻¹. (b) Gain equals loss, so the temperature stays constant (thermal steady state). (c) net 10 kW: dθ/dt = 10000 ÷ 22800 = 0.439 K s⁻¹. Mark scheme (5 marks). C1: dθ/dt = P/mc. A1: (a). B1: constant temperature. C1: net power. A1: rate = 0.439 K s⁻¹.', 5, NULL, NULL),
('dab569ba-7d91-53cb-9476-59749d215fc9', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 45, 45, 'A 0.12 kg block of an unknown metal at 98 °C is placed in 0.15 kg of water at 22 °C in a 0.080 kg copper calorimeter (c = 390 J kg⁻¹ K⁻¹), also at 22 °C. The final temperature is 26 °C. (a) Calculate the energy gained by the water and calorimeter. (b) Calculate c for the metal. (c) Suggest which metal it might be. Give only the answer to (b). Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.', NULL, 3, 'numeric'::answer_type, '306.1', 'J kg⁻¹ K⁻¹', false, NULL, false, NULL, '(a) (0.15 × 4200 + 0.080 × 390) × 4 = 2640 J. (b) c = 2645 ÷ (0.12 × 72) = 306 J kg⁻¹ K⁻¹. (c) About 300 J kg⁻¹ K⁻¹: similar to tin or a brass-like alloy (well below aluminium''s 900). Mark scheme (5 marks). C1: water + calorimeter. A1: energy gained. C1: heat lost by metal. A1: c = 306 J kg⁻¹ K⁻¹. B1: sensible identification.', 5, NULL, NULL),
('7c644104-71af-5e8c-8ece-aea1ff0b65f8', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 46, 46, 'Hot coffee (0.20 kg, at 85 °C) is poured into a 0.30 kg ceramic mug (c = 850 J kg⁻¹ K⁻¹) at 20 °C. Treat coffee as water. (a) Calculate the common temperature, ignoring losses. (b) Calculate the energy transferred to the mug. (c) Explain why pre-warming the mug keeps the coffee hotter. Give only the answer to (a). Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.', NULL, 3, 'numeric'::answer_type, '69.86', '°C', false, NULL, false, NULL, '(a) θ = (0.20 × 4200 × 85 + 0.30 × 850 × 20) ÷ (0.20 × 4200 + 0.30 × 850) = 69.9 °C. (b) 0.30 × 850 × (69.86 − 20) = 1.27 × 10⁴ J. (c) A warm mug takes less energy from the coffee, so the final temperature is higher. Mark scheme (6 marks). M1: heat balance. C1: substitution. A1: θ. C1: energy to mug. A1: θ = 69.9 °C. B1: less energy absorbed.', 6, NULL, NULL),
('60504786-2f7e-5efa-ade2-c923d779e93c', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 47, 47, 'Two cups of water, A (0.25 kg at 70 °C) and B (0.15 kg at 10 °C), are mixed in an insulated jug. (a) Calculate the final temperature. (b) Calculate the energy transferred from A to B. (c) Explain, using molecular ideas, why heat flows from A to B and not the other way. Give only the answer to (a). Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.', NULL, 3, 'numeric'::answer_type, '47.5', '°C', false, NULL, false, NULL, '(a) θ = (0.25 × 70 + 0.15 × 10) ÷ 0.40 = 47.5 °C. (b) E = 0.25 × 4200 × (70 − 47.5) = 2.36 × 10⁴ J. (c) A''s molecules have the higher mean kinetic energy; in collisions energy is passed, on average, from faster to slower molecules until the mean energies are equal. Mark scheme (5 marks). M1: weighted mean. A1: θ. C1: E = mcΔθ. A1: θ = 47.5 °C. B1: molecular explanation.', 5, NULL, NULL),
('1c5ee584-1c53-5208-8f1d-6b567f07c425', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 48, 48, 'A 0.50 kg block of steel (c = 450 J kg⁻¹ K⁻¹) at 20 °C and a 0.50 kg block of aluminium (c = 900 J kg⁻¹ K⁻¹) at 80 °C are placed together in an insulated box. (a) State which block''s temperature changes more, and why. (b) Calculate the final temperature. (c) Calculate the energy transferred. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '60', '°C', false, NULL, false, NULL, '(a) The steel: it has the smaller heat capacity, so the same energy gives a bigger temperature change. (b) θ = (225 × 20 + 450 × 80) ÷ (225 + 450) = 60.0 °C. (c) E = 450 × (80 − 60) = 9000 J. Mark scheme (6 marks). B1: steel. B1: smaller heat capacity. M1: heat balance. A1: θ = 60.0 °C. C1: E = CΔθ. A1: 9000 J.', 6, NULL, NULL),
('a38b41e7-e1e7-5245-bf57-334731200191', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 49, 49, 'An electrically heated hot-water tank holds 150 kg of water at 60 °C. Overnight it cools to 48 °C. (a) Calculate the energy lost. (b) Calculate the average rate of heat loss over 10 hours. (c) Suggest how the tank could be modified to reduce the loss. Give only the answer to (b). Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.', NULL, 3, 'numeric'::answer_type, '210', 'W', false, NULL, false, NULL, '(a) E = 150 × 4200 × 12 = 7.56 × 10⁶ J. (b) P = 7.56 × 10⁶ ÷ 36000 = 210 W. (c) Thicker insulation (lagging) with low thermal conductivity, and reducing the surface area or temperature difference. Mark scheme (5 marks). C1: E = mcΔθ. A1: E. C1: P = E/t with t in s. A1: P = 210 W. B1: insulation.', 5, NULL, NULL),
('c2ba79a2-5ce7-5f20-ae70-6eac0d366682', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '57029f9b-b999-54ce-809e-427abcb1c520', 'a-level', '19.4', '9702 coursebook 19.4 · Thermal equilibrium', 50, 50, 'A metal sphere at 400 °C is dropped into an insulated container with 1.0 kg of water at 15 °C. The water rises to 25 °C, and 2.0 g of it boils away when the sphere enters. (a) Calculate the energy to warm the water. (b) Calculate the energy to boil the 2.0 g (it was effectively heated from 15 °C and boiled). (c) Calculate the heat capacity of the sphere. Give only the answer to (c). Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹. Take the specific latent heat of vaporisation of water as 2.26 × 10⁶ J kg⁻¹.', NULL, 3, 'numeric'::answer_type, '125.7', 'J K⁻¹', false, NULL, false, NULL, '(a) 0.998 × 4200 × 10 = 4.19 × 10⁴ J. (b) 0.002 × (4200 × 85 + 2.26 × 10⁶) = 5230 J. (c) C = (4.192 × 10⁴ + 5234) ÷ (400 − 25) = 126 J K⁻¹. Mark scheme (6 marks). C1: water warming. A1: (a). C1: heating and boiling the 2.0 g. A1: (b). C1: C = E/Δθ. A1: C = 126 J K⁻¹.', 6, NULL, NULL)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('2884fce1-0644-53a3-9839-80175b45ab1c', 'a9b6c2e4-4543-5a1c-ba98-f59fd94872f0', 'They have the same internal energy', 'A', false, 0),
('e4a89a75-8425-5455-a73d-64c5c8c54e9c', 'a9b6c2e4-4543-5a1c-ba98-f59fd94872f0', 'They have the same mass', 'B', false, 1),
('f1d781c6-ebc7-53f5-b1de-4b4bfcb78858', 'a9b6c2e4-4543-5a1c-ba98-f59fd94872f0', 'They are at the same temperature', 'C', true, 2),
('6134cfa4-3d4e-5283-98b5-47cfd7ce6690', 'a9b6c2e4-4543-5a1c-ba98-f59fd94872f0', 'They are made of the same material', 'D', false, 3),
('e6f40e19-5582-5b6d-9f08-169c3a4a930b', '074afd7e-0ba2-578c-8796-ae33e3b587b6', 'From the hotter body to the colder body', 'A', true, 0),
('b82323e5-b08b-56f0-aa65-6fd5b87cf5dc', '074afd7e-0ba2-578c-8796-ae33e3b587b6', 'From the body with more internal energy to the body with less', 'B', false, 1),
('df3dce7c-b301-5123-8c2c-d546c2d9ae54', '074afd7e-0ba2-578c-8796-ae33e3b587b6', 'From the larger body to the smaller body', 'C', false, 2),
('4a302a65-0494-56c5-a6e9-adbadda21d68', '074afd7e-0ba2-578c-8796-ae33e3b587b6', 'In both directions equally, always', 'D', false, 3),
('8b35d62c-59a5-5d55-b494-587c9e236342', '989b8999-f0f1-5d67-9134-f768a70017dd', 'It has run out of mercury', 'A', false, 0),
('ff64b3dd-7699-5338-a4a4-de4680f31184', '989b8999-f0f1-5d67-9134-f768a70017dd', 'The tea has stopped losing energy', 'B', false, 1),
('40e477c6-c849-5df2-bb24-98259f9d322b', '989b8999-f0f1-5d67-9134-f768a70017dd', 'The thermometer has reached its maximum', 'C', false, 2),
('a143ae1e-2230-5144-9dbb-4531970cfbe2', '989b8999-f0f1-5d67-9134-f768a70017dd', 'It has reached thermal equilibrium with the tea', 'D', true, 3),
('a02522f6-ad77-54b5-9d13-2d42378028ae', '70c501cb-6083-5359-b4e9-c2818f1010d2', 'The tea must have more internal energy', 'A', false, 0),
('e1470d90-f083-5e93-b0a2-31df491ee331', '70c501cb-6083-5359-b4e9-c2818f1010d2', 'The iceberg can have more internal energy but the tea is at the higher temperature', 'B', true, 1),
('fcb550b5-f528-56cd-9f9c-cd307232b155', '70c501cb-6083-5359-b4e9-c2818f1010d2', 'They have the same internal energy', 'C', false, 2),
('75491a16-8b25-57b1-bec3-d2591ceca14f', '70c501cb-6083-5359-b4e9-c2818f1010d2', 'The iceberg is hotter', 'D', false, 3),
('31549839-ac2c-572d-abd2-ccd2e0138d90', '4e121c19-3859-5a47-a0a0-1a73ed3cf33c', 'A is hotter than C', 'A', false, 0),
('eac13ef0-984c-5d9b-9043-0b86fefbf037', '4e121c19-3859-5a47-a0a0-1a73ed3cf33c', 'C is hotter than A', 'B', false, 1),
('b930e8c6-8e95-54fb-ade0-d13409db2877', '4e121c19-3859-5a47-a0a0-1a73ed3cf33c', 'A and C are in thermal equilibrium', 'C', true, 2),
('9c98eb4b-892d-5986-a670-6c9e1dade8e1', '4e121c19-3859-5a47-a0a0-1a73ed3cf33c', 'Nothing can be concluded about A and C', 'D', false, 3),
('c2780830-f054-52a3-a872-556abbf3a4b1', 'dd5f3638-492d-5889-92bb-5093254afb73', 'Both are at the same temperature; copper conducts heat from the hand faster', 'A', true, 0),
('e4819a23-768e-5682-ae51-e6ca87e299bd', 'dd5f3638-492d-5889-92bb-5093254afb73', 'The copper is at a lower temperature', 'B', false, 1),
('b079ea89-a48b-5b44-80e7-e3da98048c67', 'dd5f3638-492d-5889-92bb-5093254afb73', 'The wood is at a higher temperature', 'C', false, 2),
('6e7d8c9f-38b5-582a-ba55-3e454de6aa38', 'dd5f3638-492d-5889-92bb-5093254afb73', 'Copper has no internal energy', 'D', false, 3),
('ffb3b64f-91ee-577b-849b-0ea659188e5f', '1fd8f4cd-12c9-5676-a78b-b22491f89851', '1200 J', 'A', false, 0),
('007c1b3f-7ced-595a-a4d1-17a3e4cbd0d4', '1fd8f4cd-12c9-5676-a78b-b22491f89851', 'Less than 2400 J, because temperature is lost', 'B', false, 1),
('173eb4c4-0f0a-5272-8b82-67353d9b5458', '1fd8f4cd-12c9-5676-a78b-b22491f89851', '4800 J', 'C', false, 2),
('cfabd789-ef15-5f1a-8f53-f9a73dc22f52', '1fd8f4cd-12c9-5676-a78b-b22491f89851', '2400 J', 'D', true, 3),
('32bd2476-836b-5a47-ab5e-3eeb992b7fc8', '0e173df0-6329-56c3-be17-09ca4c912cd7', 'Internal energy', 'A', false, 0),
('a9c37af7-896a-5782-9320-1427982b3758', '0e173df0-6329-56c3-be17-09ca4c912cd7', 'Temperature', 'B', true, 1),
('c1fe2660-74c4-5aba-bc13-ddb817c36cf7', '0e173df0-6329-56c3-be17-09ca4c912cd7', 'Specific heat capacity', 'C', false, 2),
('748d8e93-3d90-5b67-a6da-151d0f84b75c', '0e173df0-6329-56c3-be17-09ca4c912cd7', 'Mass', 'D', false, 3),
('2c75e970-9e7c-576c-9950-97d8ec9b9dbe', 'dd6c5fe5-db6f-5315-8c96-6ebe7983f272', 'The drink makes its own heat', 'A', false, 0),
('03d20398-9915-5fc1-a9da-45b2fb50b96d', 'dd6c5fe5-db6f-5315-8c96-6ebe7983f272', 'The room cools to the drink''s temperature', 'B', false, 1),
('b89e4bbc-3e29-5bf0-a68f-26dc23b98382', 'dd6c5fe5-db6f-5315-8c96-6ebe7983f272', 'Energy flows into the drink until it reaches thermal equilibrium with the room', 'C', true, 2),
('13e7451b-18d0-5569-8499-dc0e4fed1c75', 'dd6c5fe5-db6f-5315-8c96-6ebe7983f272', 'The drink''s internal energy is constant', 'D', false, 3),
('02bc2cc2-97b3-5a23-95ed-0577f7a7f93d', '6e18859c-cf94-5c4b-a768-c7a48ea052de', 'A measure of the average random kinetic energy of the particles', 'A', true, 0),
('f758c1d1-4aeb-59f7-b46b-666bb0452d8f', '6e18859c-cf94-5c4b-a768-c7a48ea052de', 'The total energy of the particles', 'B', false, 1),
('00a5e084-e536-5e66-9307-c8ce878a3919', '6e18859c-cf94-5c4b-a768-c7a48ea052de', 'The amount of heat in a body', 'C', false, 2),
('6efc3dd6-7f92-5366-b49d-06a7bdb3bc23', '6e18859c-cf94-5c4b-a768-c7a48ea052de', 'The potential energy of the particles', 'D', false, 3),
('1bea466e-1816-5052-b7a3-09478c7e6d55', '583cdfaa-901c-57b2-83d4-4f2b5cd267ee', 'The thermometer was too accurate', 'A', false, 0),
('55c969d1-bbdd-5ae9-86f3-6eb5eb588208', '583cdfaa-901c-57b2-83d4-4f2b5cd267ee', 'Too much stirring was done', 'B', false, 1),
('64799bb9-5391-56f5-98d9-41fa2f828dda', '583cdfaa-901c-57b2-83d4-4f2b5cd267ee', 'The masses were measured in kg', 'C', false, 2),
('0cc8b508-e9ee-5e4d-a88e-33d2a7245be9', '583cdfaa-901c-57b2-83d4-4f2b5cd267ee', 'Heat was lost to the container and surroundings', 'D', true, 3),
('49e71438-a6b2-5b92-b281-07a4eb18c052', 'a394c93c-ad68-566a-8422-876b2d31f244', 'The water cools faster', 'A', false, 0),
('cb2e55c9-d08f-5cd1-bcc6-5933dbf17c7d', 'a394c93c-ad68-566a-8422-876b2d31f244', 'The copper cools faster, because it has a smaller specific heat capacity', 'B', true, 1),
('f76333e0-6f1f-58a1-bc97-d754251e0c9b', 'a394c93c-ad68-566a-8422-876b2d31f244', 'They cool at the same rate because they have the same mass', 'C', false, 2),
('45b3d763-e19a-5157-851e-52c4d5734d2d', 'a394c93c-ad68-566a-8422-876b2d31f244', 'The copper ends at a lower final temperature', 'D', false, 3),
('05962656-d286-57b9-87db-1c741e4bb38d', '35ab980a-ad7d-5b91-b857-2e27425a8c74', 'The pan still has more heat than the water', 'A', false, 0),
('99c1a9e9-d75a-581b-b900-2ad301193f69', '35ab980a-ad7d-5b91-b857-2e27425a8c74', 'Heat now flows from water to pan', 'B', false, 1),
('189f0d46-c57f-51fc-9eec-c9dececabadd', '35ab980a-ad7d-5b91-b857-2e27425a8c74', 'The pan and water are in thermal equilibrium; the water''s temperature rise was smaller because its heat capacity is larger', 'C', true, 2),
('58603e30-b926-5e10-b14a-69d197e52886', '35ab980a-ad7d-5b91-b857-2e27425a8c74', 'The pan is hotter because metal holds heat', 'D', false, 3),
('0bdfbc72-1e38-5ac6-992f-1b76acd70e8b', 'f01849ff-0c63-5f70-8dbc-1c87bdaf498a', 'It makes the calculated value too small', 'A', true, 0),
('4f36e83b-c5b9-5446-8f82-1531e11caf66', 'f01849ff-0c63-5f70-8dbc-1c87bdaf498a', 'It makes it too large', 'B', false, 1),
('d47c1b17-8c67-5e83-805d-a4e72107f973', 'f01849ff-0c63-5f70-8dbc-1c87bdaf498a', 'It has no effect', 'C', false, 2),
('ca30342f-2dac-55c2-b008-5b3407c334eb', 'f01849ff-0c63-5f70-8dbc-1c87bdaf498a', 'It makes it negative', 'D', false, 3),
('9721ffd0-6647-5059-bb19-cee65b31da34', '28ad33f4-ed3e-5a2a-9524-3155345f05c3', 'The bath, because it has a larger surface', 'A', false, 0),
('3cf4d9bc-b6b1-5f2e-8585-949fbcd70668', '28ad33f4-ed3e-5a2a-9524-3155345f05c3', 'Both at the same time', 'B', false, 1),
('a207f4d6-5f58-51ea-8fda-14be71809c68', '28ad33f4-ed3e-5a2a-9524-3155345f05c3', 'Neither, because they are at the same temperature', 'C', false, 2),
('8d886627-090f-5445-a793-d2a7fac72977', '28ad33f4-ed3e-5a2a-9524-3155345f05c3', 'The cup, because it has a much smaller heat capacity', 'D', true, 3),
('78f178ea-f434-5cc3-802d-fe03b4667216', '8c2bf181-2150-5f3f-a3f2-ad23fb483b81', 'The thermometer needs time to warm its batteries', 'A', false, 0),
('cd331519-916e-57e2-b7ce-4a859c19ee9e', '8c2bf181-2150-5f3f-a3f2-ad23fb483b81', 'Before then, heat is still flowing and the thermometer is not at the object''s temperature', 'B', true, 1),
('a1906ed7-7c58-5838-b2b4-cf881bd2a816', '8c2bf181-2150-5f3f-a3f2-ad23fb483b81', 'Temperature cannot change', 'C', false, 2),
('5423d33c-ce34-5caf-833e-7512cd1bf837', '8c2bf181-2150-5f3f-a3f2-ad23fb483b81', 'The object must cool to room temperature first', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('d70b062d-f63c-52f1-af4f-7918f1fd6087', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 9, 9, 'Convert the boiling point of nitrogen, −196 °C, to kelvin.', NULL, 1, 'numeric'::answer_type, '77.15', 'K', false, NULL, false, NULL, 'T = θ + 273.15 = −196 + 273.15 = 77.15 K. Mark scheme (1 mark). A1: T = 77.1 K.', 1, NULL, NULL),
('4a7da260-59df-5a93-a6a4-4a3ad68c8b66', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 10, 10, 'The surface of the Sun is at about 5800 K. Express this in degrees Celsius.', NULL, 1, 'numeric'::answer_type, '5527', '°C', false, NULL, false, NULL, 'θ = T − 273 = 5800 − 273 = 5527 °C ≈ 5500 °C. Mark scheme (1 mark). A1: θ = 5500 °C.', 1, NULL, NULL),
('e6537f5d-0380-5f28-b720-7d82b6a36b9f', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 11, 11, 'What is the temperature of absolute zero on the Celsius scale?', NULL, 1, 'multiple_choice'::answer_type, '−273.15 °C', NULL, false, NULL, false, NULL, 'T = 0 K corresponds to θ = −273.15 °C. Mark scheme (1 mark). B1: C (−273.15 °C).', 1, NULL, NULL),
('78c0f061-2652-5377-917f-0eec1635b13f', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 12, 12, 'Why can there be no temperature below 0 K?', NULL, 1, 'multiple_choice'::answer_type, 'At absolute zero the internal energy of a system is a minimum; it cannot be reduced further', NULL, false, NULL, false, NULL, 'Absolute zero is the temperature at which the particles have minimum energy; nothing can be colder. Mark scheme (1 mark). B1: A (At absolute zero the internal energy of a system is a minimum; it cannot be reduced further).', 1, NULL, NULL),
('81a6bed2-6acd-5e78-b4ab-e66411bb6074', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 13, 13, 'A gas cools by 35 °C. State its change in temperature in kelvin, and explain why.', NULL, 1, 'numeric'::answer_type, '35', 'K', false, NULL, false, NULL, 'A change of 1 °C equals a change of 1 K (the scales have the same interval size): ΔT = 35 × 1 = 35 K. Mark scheme (2 marks). B1: equal-sized degrees. A1: ΔT = 35 K.', 2, NULL, NULL),
('c2f4d2ef-23d0-542f-a445-c112f2eba7b0', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 14, 14, 'Which property is used in a liquid-in-glass thermometer as the thermometric property?', NULL, 1, 'multiple_choice'::answer_type, 'The expansion of the liquid', NULL, false, NULL, false, NULL, 'A thermometric property must change continuously and measurably with temperature: here, the length of the liquid column. Mark scheme (1 mark). B1: D (The expansion of the liquid).', 1, NULL, NULL),
('6c4a6cb3-90f0-5305-a50c-59436064f106', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 15, 15, 'The thermodynamic temperature scale does not depend on the property of any particular substance. Why is this an advantage?', NULL, 1, 'multiple_choice'::answer_type, 'All correctly calibrated thermometers then agree at every temperature', NULL, false, NULL, false, NULL, 'Scales based on, say, mercury expansion can disagree between fixed points; the thermodynamic scale is absolute. Mark scheme (1 mark). B1: B (All correctly calibrated thermometers then agree at every temperature).', 1, NULL, NULL),
('b8edf4a7-f03c-5143-8247-2677a1a5b37f', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 16, 16, 'Room temperature is 21 °C. Convert it to kelvin.', NULL, 1, 'numeric'::answer_type, '294.1', 'K', false, NULL, false, NULL, 'T = 21 + 273.15 = 294.15 K ≈ 294 K. Mark scheme (1 mark). A1: T = 294 K.', 1, NULL, NULL),
('88e7d3b7-8cb7-5e46-9afc-f1fe54068e80', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 17, 17, 'Which two fixed points define the thermodynamic temperature scale in the 9702 course?', NULL, 1, 'multiple_choice'::answer_type, 'Absolute zero and the triple point of pure water (273.16 K)', NULL, false, NULL, false, NULL, 'The kelvin is defined using absolute zero (0 K) and the triple point of water (273.16 K). Mark scheme (1 mark). B1: C (Absolute zero and the triple point of pure water (273.16 K)).', 1, NULL, NULL),
('0d0934e5-acd6-5eec-a701-796ce5833c08', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 18, 18, 'A freezer is at 255 K. What is this in °C?', NULL, 1, 'numeric'::answer_type, '-18.15', '°C', false, NULL, true, NULL, 'θ = T − 273.15 = 255 − 273.15 = −18 °C. Mark scheme (2 marks). C1: subtract 273.15. A1: θ = −18 °C.', 2, NULL, NULL),
('8a47dea7-f310-50da-9ab3-0dceef72ea10', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 19, 19, 'Which property of a thermocouple is used to measure temperature?', NULL, 1, 'multiple_choice'::answer_type, 'The e.m.f. produced between its two junctions', NULL, false, NULL, false, NULL, 'A thermocouple gives an e.m.f. that depends on the temperature difference between its junctions. Mark scheme (1 mark). B1: A (The e.m.f. produced between its two junctions).', 1, NULL, NULL),
('86b2718f-ed9f-515e-8a8a-3276565fe9e7', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 20, 20, 'A temperature rises from 250 K to 310 K. Calculate the rise in °C.', NULL, 1, 'numeric'::answer_type, '60', '°C', false, NULL, false, NULL, 'The interval is the same on both scales: Δθ = 310 − 250 = 60 °C. Mark scheme (2 marks). B1: equal intervals. A1: Δθ = 60 °C.', 2, NULL, NULL),
('eff0bf78-b7cd-513f-bfb9-a7132868469f', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 21, 21, 'A thermistor''s resistance falls as temperature rises. Why is it useful as a thermometer?', NULL, 1, 'multiple_choice'::answer_type, 'Its resistance changes measurably and continuously with temperature', NULL, false, NULL, false, NULL, 'Any property that varies continuously and reproducibly with temperature can be used: here, resistance. Mark scheme (1 mark). B1: D (Its resistance changes measurably and continuously with temperature).', 1, NULL, NULL),
('d923d9c7-ea57-55ed-89e8-2b3f445ad1d1', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 22, 22, 'Liquid helium boils at 4.2 K. Express this in °C.', NULL, 1, 'numeric'::answer_type, '-268.9', '°C', false, NULL, true, NULL, 'θ = 4.2 − 273.15 = −268.95 °C ≈ −269 °C. Mark scheme (2 marks). C1: subtract 273.15. A1: θ = −269 °C.', 2, NULL, NULL),
('06bac12a-c584-5250-ad0c-d2922fbc09bb', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 23, 23, 'Express the triple point of water, 273.16 K, in degrees Celsius.', NULL, 1, 'numeric'::answer_type, '0.01', '°C', false, NULL, false, NULL, 'θ = 273.16 − 273.15 = 0.01 °C. Mark scheme (2 marks). C1: subtract 273.15. A1: θ = 0.01 °C.', 2, NULL, NULL),
('36d20464-df73-5037-b7f9-c7148bdbcfb1', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 24, 24, 'A resistance thermometer has resistance 100.0 Ω at 0 °C and 138.5 Ω at 100 °C. Assuming a linear scale, calculate the temperature when its resistance is 119.2 Ω.', NULL, 2, 'numeric'::answer_type, '49.87', '°C', false, NULL, false, NULL, 'θ = (R − R₀)/(R₁₀₀ − R₀) × 100 = (119.2 − 100.0) ÷ (138.5 − 100.0) × 100 = 49.9 °C. Mark scheme (3 marks). C1: linear interpolation formula. C1: substitution. C1: × 100.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg03f4a706-t fg03f4a706-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg03f4a706-t">Calibration line</title><desc id="fg03f4a706-d">Calibration graph of resistance against temperature: a straight line from 100.0 Ω at 0 °C to 138.5 Ω at 100 °C. A dashed line marks 119.2 Ω.</desc><line x1="36.2" y1="34" x2="36.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="99" y1="34" x2="99" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="161.9" y1="34" x2="161.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="224.8" y1="34" x2="224.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="287.7" y1="34" x2="287.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="350.6" y1="34" x2="350.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="221.2" x2="382" y2="221.2" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="179.6" x2="382" y2="179.6" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="138" x2="382" y2="138" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="96.4" x2="382" y2="96.4" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="54.8" x2="382" y2="54.8" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="242" x2="36.2" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="36.2,24 39.1,30.3 33.2,30.3" style="fill:currentColor;stroke:none"/><line x1="36.2" y1="242" x2="36.2" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="36.2" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="99" y1="242" x2="99" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="99" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">20</text><line x1="161.9" y1="242" x2="161.9" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="161.9" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">40</text><line x1="224.8" y1="242" x2="224.8" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="224.8" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">60</text><line x1="287.7" y1="242" x2="287.7" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="287.7" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">80</text><line x1="350.6" y1="242" x2="350.6" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="350.6" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">100</text><line x1="32.2" y1="221.2" x2="36.2" y2="221.2" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="221.2" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">100</text><line x1="32.2" y1="179.6" x2="36.2" y2="179.6" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="179.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">110</text><line x1="32.2" y1="138" x2="36.2" y2="138" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="138" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">120</text><line x1="32.2" y1="96.4" x2="36.2" y2="96.4" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="96.4" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">130</text><line x1="32.2" y1="54.8" x2="36.2" y2="54.8" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="54.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">140</text><text x="209.1" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">θ / °C</text><text x="32.2" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">R / Ω</text><line x1="36.2" y1="141.3" x2="382" y2="141.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><text x="380" y="131.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">119.2 Ω</text><polyline points="36.2,221.2 350.6,61" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Calibration graph of resistance against temperature: a straight line from 100.0 Ω at 0 °C to 138.5 Ω at 100 °C. A dashed line marks 119.2 Ω.'),
('b73a0d0b-e9bb-5284-b17b-0daf8cd1f0e6', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 25, 25, 'A liquid-in-glass thermometer has a 4.0 cm column at 0 °C and 24.0 cm at 100 °C. What temperature is shown when the column is 15.0 cm long?', NULL, 2, 'numeric'::answer_type, '55', '°C', false, NULL, false, NULL, 'θ = (15.0 − 4.0) ÷ (24.0 − 4.0) × 100 = 55 °C. Mark scheme (3 marks). C1: length change from 0 °C. C1: fraction of the interval. C1: × 100.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fge43deb35-t fge43deb35-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge43deb35-t">Calibration line</title><desc id="fge43deb35-d">Calibration graph of column length against temperature: a straight line from 4.0 cm at 0 °C to 24.0 cm at 100 °C. A dashed line marks 15.0 cm.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93.5" y1="34" x2="93.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="157.6" y1="34" x2="157.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="221.7" y1="34" x2="221.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="285.8" y1="34" x2="285.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="349.9" y1="34" x2="349.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="382" y2="242" style=