('c0254237-4fcb-5ea1-8062-28e6a8af4d15', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 42, 42, 'Air in a sealed flask is at 20 °C and 1.00 × 10⁵ Pa. The flask is heated at constant volume. (a) Explain why pressure is proportional to kelvin temperature, not Celsius temperature. (b) Calculate the pressure at 100 °C. (c) Calculate the temperature in °C at which the pressure would double. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '313.1', '°C', false, NULL, false, NULL, '(a) p ∝ T only when T is measured from absolute zero, where p → 0. (b) p = 1.00 × 10⁵ × 373.15 ÷ 293.15 = 1.27 × 10⁵ Pa. (c) Double p needs double T: 2 × 293.15 = 586.3 K, θ = 586.3 − 273.15 = 313 °C. Mark scheme (6 marks). B1: proportional to absolute temperature. C1: p₂ = p₁T₂/T₁. A1: p. C1: double T in kelvin. C1: convert. A1: θ = 313 °C.', 6, NULL, NULL),
('a6185eba-661f-550a-bce8-8e7a0871c9bb', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 43, 43, 'The resistance R of a copper wire varies as R = R₀(1 + αθ), with α = 4.3 × 10⁻³ K⁻¹ and R₀ = 12.0 Ω at 0 °C. (a) Calculate R at 100 °C. (b) The wire is in a furnace and R = 40.0 Ω. Calculate θ. (c) Convert θ to kelvin. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '542.6', '°C', false, NULL, false, NULL, '(a) R = 12.0 × (1 + 4.3 × 10⁻³ × 100) = 17.2 Ω. (b) θ = (R/R₀ − 1)/α = (40.0 ÷ 12.0 − 1) ÷ 4.3 × 10⁻³ = 543 °C. (c) T = 542.6 + 273 = 816 K. Mark scheme (5 marks). A1: R at 100 °C. M1: rearranged. C1: substitution. A1: θ = 543 °C. B1: T.', 5, NULL, NULL),
('e1e47512-59ea-595b-bee5-e1b1569579e6', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 44, 44, 'A student uses the expansion of alcohol in a thermometer. Between 0 °C and 100 °C the column grows from 2.0 cm to 22.0 cm, but at the true temperature 50 °C it is 11.5 cm. (a) Calculate the temperature this thermometer indicates at 11.5 cm. (b) Calculate the error. (c) Explain what this tells you about alcohol''s expansion. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '-2.5', '°C', false, NULL, true, NULL, '(a) θ = (11.5 − 2.0) ÷ 20.0 × 100 = 47.5 °C. (b) error = 47.5 − 50 = −2.50 °C. (c) Alcohol''s expansion is not exactly linear with temperature: it expands less per kelvin at lower temperatures. Mark scheme (6 marks). C1: interpolation. A1: 47.5 °C. C1: error. A1: −2.5 °C. B1: non-linear expansion. B1: direction.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgfb26e6f2-t fgfb26e6f2-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgfb26e6f2-t">Alcohol thermometer scale</title><desc id="fgfb26e6f2-d">Calibration line for the alcohol thermometer: from 2.0 cm at 0 °C to 22.0 cm at 100 °C. A dashed line marks the 11.5 cm reading at the true temperature of 50 °C.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93.5" y1="34" x2="93.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="157.6" y1="34" x2="157.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="221.7" y1="34" x2="221.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="285.8" y1="34" x2="285.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="349.9" y1="34" x2="349.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="198.7" x2="382" y2="198.7" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="155.3" x2="382" y2="155.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="112" x2="382" y2="112" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="68.7" x2="382" y2="68.7" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="29.4" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="29.4,24 32.4,30.3 26.5,30.3" style="fill:currentColor;stroke:none"/><line x1="29.4" y1="242" x2="29.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="93.5" y1="242" x2="93.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="93.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">20</text><line x1="157.6" y1="242" x2="157.6" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="157.6" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">40</text><line x1="221.7" y1="242" x2="221.7" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="221.7" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">60</text><line x1="285.8" y1="242" x2="285.8" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="285.8" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">80</text><line x1="349.9" y1="242" x2="349.9" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="349.9" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">100</text><line x1="25.4" y1="242" x2="29.4" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="25.4" y1="198.7" x2="29.4" y2="198.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="198.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">5</text><line x1="25.4" y1="155.3" x2="29.4" y2="155.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="155.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">10</text><line x1="25.4" y1="112" x2="29.4" y2="112" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="112" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">15</text><line x1="25.4" y1="68.7" x2="29.4" y2="68.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="68.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">20</text><text x="205.7" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">θ / °C</text><text x="25.4" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">column length / cm</text><line x1="29.4" y1="142.3" x2="382" y2="142.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><text x="380" y="132.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">11.5 cm</text><polyline points="29.4,224.7 349.9,51.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Calibration line for the alcohol thermometer: from 2.0 cm at 0 °C to 22.0 cm at 100 °C. A dashed line marks the 11.5 cm reading at the true temperature of 50 °C.'),
('7fc77add-dbb9-5a6c-a72b-8eb0a5f4e0a4', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 45, 45, 'Mercury freezes at −39 °C and boils at 357 °C. (a) Express both in kelvin. (b) Explain why a mercury thermometer cannot measure the temperature of liquid nitrogen (77 K). (c) Calculate the range of a mercury thermometer in kelvin. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '396', 'K', false, NULL, false, NULL, '(a) 234 K and 630 K. (b) 77 K is below 234 K, so the mercury would be solid. (c) range = 357 − (−39) = 396 K (equal to 396 °C because intervals are equal). Mark scheme (5 marks). A1: both in K. B1: mercury freezes. C1: difference. A1: range = 396 K. B1: equal intervals.', 5, NULL, NULL),
('12f7ba3d-df44-57a6-bf14-dc6a22aa0fd9', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 46, 46, 'A sealed bottle of air is put in a freezer at −18 °C after being filled at 22 °C and 1.01 × 10⁵ Pa. (a) Calculate the pressure inside at −18 °C. (b) Calculate the force on the 4.0 cm diameter cap due to the pressure difference. (c) Explain why using Celsius temperatures in p₁/T₁ = p₂/T₂ gives a meaningless answer. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '17.2', 'N', false, NULL, false, NULL, '(a) p = 1.01 × 10⁵ × 255.15 ÷ 295.15 = 8.73 × 10⁴ Pa. (b) Δp = 1.01 × 10⁵ − 8.731 × 10⁴ = 1.37 × 10⁴ Pa, area = π × 0.020² = 0.00126 m², F = 1.369 × 10⁴ × 0.001257 = 17.2 N (inwards). (c) The Celsius value −18 would give a negative pressure: p ∝ T only for absolute temperature. Mark scheme (6 marks). C1: p₂ = p₁T₂/T₁ in kelvin. A1: p. C1: Δp. C1: F = ΔpA. A1: F = 17.2 N. B1: Celsius gives negative/meaningless.', 6, NULL, NULL),
('ad092efe-942d-5455-9621-167d0526f1e4', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 47, 47, 'A digital thermometer uses a thermistor whose resistance is 3.3 kΩ at 25 °C and 1.1 kΩ at 60 °C. (a) Calculate the change in resistance per kelvin, assuming linearity. (b) Use it to estimate the temperature when R = 2.0 kΩ. (c) Express that temperature in kelvin. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '45.68', '°C', false, NULL, false, NULL, '(a) (3.3 − 1.1) ÷ 35 = 0.0629 kΩ per K (a fall). (b) θ = 25 + (3.3 − 2.0) ÷ 0.06286 = 45.7 °C. (c) T = 45.68 + 273 = 319 K. Mark scheme (5 marks). C1: gradient. A1: (a). C1: interpolation. A1: θ = 45.7 °C. B1: kelvin.', 5, NULL, NULL),
('cf7ed8d6-6d3d-5a4e-8913-af43e216b023', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 48, 48, 'A constant-volume gas thermometer bulb is at 273.16 K (triple point) with pressure 6.50 × 10⁴ Pa. It is placed in boiling sulfur and the pressure becomes 1.70 × 10⁵ Pa. (a) Calculate the temperature in kelvin. (b) Convert to °C. (c) Explain why the gas must be kept at low pressure for the scale to agree with the thermodynamic scale. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '714.4', 'K', false, NULL, false, NULL, '(a) T = 273.16 × 1.70 × 10⁵ ÷ 6.50 × 10⁴ = 714 K. (b) θ = 714.4 − 273.15 = 441 °C. (c) At low pressure the gas behaves ideally (molecules far apart, negligible forces), so p ∝ T exactly. Mark scheme (6 marks). C1: T ∝ p. C1: substitution. A1: T = 714 K. B1: °C. B1: ideal at low pressure. B1: reason.', 6, NULL, NULL),
('7d4c0391-8cb1-59df-a6d4-7e4251af9192', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 49, 49, 'Interstellar dust grains are at about 15 K. The cosmic microwave background is at 2.7 K. (a) Express both in °C. (b) Calculate the ratio of the grain temperature to the background temperature. (c) Explain why this ratio has meaning in kelvin but not in °C. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '5.556', NULL, false, NULL, false, NULL, '(a) −258 °C and −270.45 °C. (b) ratio = 15 ÷ 2.7 = 5.6. (c) Ratios need a true zero: the kelvin scale starts at absolute zero, the Celsius scale does not. Mark scheme (5 marks). A1: ratio = 5.6. C1: ratio in K. A1: 5.6. B1: absolute zero. B1: Celsius ratio meaningless.', 5, NULL, NULL),
('e44d430a-2230-56c3-a07d-fb409ccbb052', '732e83dd-2c22-497f-8d64-2f7a3fd69629', '44937e02-ca76-55a2-936f-ebfb890a9d89', 'a-level', '19.5', '9702 coursebook 19.5 · Temperature scales', 50, 50, 'A home-made thermometer uses the length of a mercury thread: 3.20 cm at the ice point and 18.60 cm at the steam point. In a sauna it reads 13.50 cm. (a) Calculate the sauna temperature on this thermometer''s scale. (b) Convert to kelvin. (c) Explain why a reading of exactly 100 °C would not be obtained in boiling water at the top of a mountain. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '66.88', '°C', false, NULL, false, NULL, '(a) θ = (13.50 − 3.20) ÷ (18.60 − 3.20) × 100 = 66.9 °C. (b) T = 66.88 + 273 = 340 K. (c) Water boils below 100 °C at lower air pressure, so the "steam point" is lower there. Mark scheme (6 marks). C1: interpolation. C1: substitution. A1: θ = 66.9 °C. B1: kelvin. B1: lower pressure. B1: lower boiling point.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgfdca6e7c-t fgfdca6e7c-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgfdca6e7c-t">Thermometer scale</title><desc id="fgfdca6e7c-d">Calibration line for the mercury thread: 3.20 cm at the ice point (0 °C) and 18.60 cm at the steam point (100 °C). A dashed line marks the sauna reading, 13.50 cm.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93.5" y1="34" x2="93.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="157.6" y1="34" x2="157.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="221.7" y1="34" x2="221.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="285.8" y1="34" x2="285.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="349.9" y1="34" x2="349.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="190" x2="382" y2="190" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="138" x2="382" y2="138" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="86" x2="382" y2="86" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="29.4" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="29.4,24 32.4,30.3 26.5,30.3" style="fill:currentColor;stroke:none"/><line x1="29.4" y1="242" x2="29.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="93.5" y1="242" x2="93.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="93.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">20</text><line x1="157.6" y1="242" x2="157.6" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="157.6" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">40</text><line x1="221.7" y1="242" x2="221.7" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="221.7" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">60</text><line x1="285.8" y1="242" x2="285.8" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="285.8" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">80</text><line x1="349.9" y1="242" x2="349.9" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="349.9" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">100</text><line x1="25.4" y1="242" x2="29.4" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="25.4" y1="190" x2="29.4" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="190" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">5</text><line x1="25.4" y1="138" x2="29.4" y2="138" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="138" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">10</text><line x1="25.4" y1="86" x2="29.4" y2="86" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="86" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">15</text><line x1="25.4" y1="34" x2="29.4" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">20</text><text x="205.7" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">θ / °C</text><text x="25.4" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">thread length / cm</text><line x1="29.4" y1="101.6" x2="382" y2="101.6" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><text x="380" y="91.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">13.50 cm</text><polyline points="29.4,208.7 349.9,48.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Calibration line for the mercury thread: 3.20 cm at the ice point (0 °C) and 18.60 cm at the steam point (100 °C). A dashed line marks the sauna reading, 13.50 cm.')
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
